LEFT = re.compile(r"@[A-Z][A-Z0-9_]*@")
def sub(src):
    out = src
    for k in sorted(T, key=len, reverse=True):
        out = out.replace("@" + k + "@", T[k])
    left = LEFT.findall(out)
    if left:
        raise SystemExit("unreplaced tokens %s in:\n%s" % (left, out[:300]))
    return out
def _mk(kind, cls, src):
    s = sub(src)
    try:
        if kind == "M": cls.addMethod(CtNewMethod.make(s, cls))
        elif kind == "F": cls.addField(CtField.make(s, cls))
        else: cls.addConstructor(CtNewConstructor.make(s, cls))
    except Exception as e:
        print("COMPILE ERROR in", cls.getName(), ":", str(e)[:400])
        print(s[:1500])
        raise
def M(cls, src): _mk("M", cls, src)
def F(cls, src): _mk("F", cls, src)
def C(cls, src): _mk("C", cls, src)

# ================= Assets.zip checks (every id the jar hands out or shows) =================
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "tools"))
import serverjar as _SJ                     # 0.3.11: the CACHED Assets.zip (tools/serverjar.py) - never the installed game file
ASSETS = _SJ.assets_zip()
with zipfile.ZipFile(ASSETS) as z:
    ITEM_IDS = set(os.path.basename(n)[:-5] for n in z.namelist() if n.startswith("Server/Item/Items/") and n.endswith(".json"))
def must(i):
    if i not in ITEM_IDS: raise SystemExit("unknown item id: " + i)
    return i
# 0.3 (research/Skill-Trees-2-Spec.md 4 Icons, PreRelease-Compat-Audit-1002 section 7 item 10): node ICONS must exist in BOTH game
# versions - the release Assets.zip above and, when it is installed, the 0.7 pre-release one (read-only, optional). Glider is gone in
# 0.7, so the two Acrobatics nodes that showed it use Template_Glider (in both).
ASSETS_07 = os.path.join(B.HYTALE, "install", "pre-release", "package", "game", "latest", "Assets.zip")
ITEM_IDS_07 = None
if os.environ.get("SKYY_CHECK_PRE") == "1" and os.path.isfile(ASSETS_07):     # 0.3.11: an installed game file - opt-in only
    with zipfile.ZipFile(ASSETS_07) as z:
        ITEM_IDS_07 = set(os.path.basename(n)[:-5] for n in z.namelist() if n.startswith("Server/Item/Items/") and n.endswith(".json"))
def must_icon(i):
    must(i)
    if ITEM_IDS_07 is not None and i not in ITEM_IDS_07:
        raise SystemExit("node icon %s is missing in the 0.7 pre-release Assets.zip (%s) - pick an icon both versions have" % (i, ASSETS_07))
    return i
# 0.3.12 THE ICON HOOK (research/Ability-Tree-Redesign-Spec.md 5.4): OUR OWN icon per node. Key = "<Tree>.<Id>" (a template node, e.g.
# "Mining.MDmg") or "<Class>.<NodeId>" (a class node, e.g. "Mage.A1"); value = the icon's item id - a game item or one this jar ships (the
# R4 icon round adds the art + its items here). A node with no entry keeps today's icon. Empty until an icon sheet is approved.
NODE_ICON_ART = {}
OWN_ICON_IDS = set()          # item ids this jar ships for node icons (none yet: the R4 icon round lists them with their assets)
def node_icon(key, fallback):
    a = NODE_ICON_ART.get(key)
    if not a:
        return fallback
    if a in OWN_ICON_IDS:
        return a
    if a not in ITEM_IDS:
        raise SystemExit("NODE_ICON_ART %s = %s: no such item in Assets.zip or this jar - add the icon item first" % (key, a))
    return must_icon(a)   # a game item: also in the 0.7 pre-release Assets.zip when installed (as every node icon)

# saplings: Wood_<W>_Trunk* -> Plant_Sapling_<W> (spec: every wood except Burnt and Fir)
WOODS = sorted(set(re.match(r"Wood_(.+?)_Trunk", i).group(1) for i in ITEM_IDS if re.match(r"Wood_(.+?)_Trunk", i)))
SAP_WOODS = [w for w in WOODS if "Plant_Sapling_" + w in ITEM_IDS]
# 0.3.11 REPLANT: the wood family of a felled trunk -> the vanilla sapling that grows that tree (a sapling block with Farming stages). Name match
# first (Wood_Oak_Trunk -> Plant_Sapling_Oak), then the wood its grown tree is made of (its last stage prefab: Fir -> Plant_Sapling_Spruce).
# Valid ground = the blocks tagged Type=Soil (every vanilla sapling: Support Down TagId "Type=Soil").
import collections as _rcol
with zipfile.ZipFile(ASSETS) as z:
    _rn = z.namelist()
    _rsap = {}
    _rsoil = set()
    _rall = {}
    for _n in _rn:
        if not (_n.startswith("Server/Item/Items/") and _n.endswith(".json")):
            continue
        _b = os.path.basename(_n)[:-5]
        if not (_b.startswith("Plant_Sapling_") or _b.startswith("Soil_") or "Soil" in z.read(_n).decode("utf-8-sig", "replace")[:4000]):
            continue
        try:
            _j = json.loads(z.read(_n).decode("utf-8-sig"))
        except Exception:
            continue
        _bt = _j.get("BlockType") or {}
        if _b.startswith("Plant_Sapling_"):
            _rall[_b] = _j
        if _b.startswith("Plant_Sapling_") and "Farming" in _bt:
            _rsap[_b] = _bt
        if "Soil" in (((_j.get("Tags") or {}).get("Type")) or []) and _bt:
            _rsoil.add(_b)
    for _b in _rsap:          # every sapling needs soil below (its own Support, or its Parent's: most saplings inherit Plant_Sapling_Oak's)
        _c, _sp = _b, None
        while _c and _sp is None:
            _sp = (_rall.get(_c, {}).get("BlockType") or {}).get("Support")
            _c = _rall.get(_c, {}).get("Parent")
        assert _sp is not None and {"TagId": "Type=Soil"} in (_sp.get("Down") or []), "0.3.11: %s no longer needs soil below (%s)" % (_b, _sp)
    _rpref = [_n for _n in _rn if _n.startswith("Server/Prefabs/") and _n.endswith(".prefab.json")]
    REPL = dict((w, "Plant_Sapling_" + w) for w in WOODS if "Plant_Sapling_" + w in _rsap)
    for _sid in sorted(_rsap):
        _st = ((_rsap[_sid].get("Farming") or {}).get("Stages") or {}).get("Default") or []
        _ps = [p_["Path"] for s_ in _st for p_ in s_.get("Prefabs", [])]
        if not _ps:
            continue
        _c = [n_ for n_ in _rpref if n_.endswith("/" + _ps[-1])]
        if not _c:
            continue
        _fam = _rcol.Counter(re.findall(r'"Wood_([A-Za-z_]+?)_Trunk"', z.read(_c[0]).decode("utf-8-sig", "replace"))).most_common(1)
        if _fam and _fam[0][0] in WOODS and _fam[0][0] not in REPL:
            REPL[_fam[0][0]] = _sid
REPL_FAM = sorted(REPL)
REPL_SAP = [REPL[w] for w in REPL_FAM]
REPL_SOIL = sorted(_rsoil)
assert REPL.get("Oak") == "Plant_Sapling_Oak" and REPL.get("Birch") == "Plant_Sapling_Birch" and REPL.get("Fir") == "Plant_Sapling_Spruce", REPL
assert "Burnt" not in REPL and all(v in ITEM_IDS for v in REPL_SAP) and len(REPL_FAM) >= 25, REPL
assert "Soil_Grass" in REPL_SOIL and "Soil_Dirt" in REPL_SOIL and "Soil_Dirt_Tilled" in REPL_SOIL and "Rock_Stone" not in REPL_SOIL, REPL_SOIL[:20]
assert "Oak" in SAP_WOODS and "Burnt" not in SAP_WOODS and "Fir" not in SAP_WOODS, SAP_WOODS
# seeds: Plant_Crop_<C>_Block -> Plant_Seeds_<C> (spec: none for Berry, Berry_Wet, Berry_Winter, Wild_Grass)
CROPS = sorted(set(re.match(r"Plant_Crop_(.+?)_Block$", i).group(1) for i in ITEM_IDS if re.match(r"Plant_Crop_(.+?)_Block$", i)))
SEED_CROPS = [c for c in CROPS if "Plant_Seeds_" + c in ITEM_IDS]
assert "Wheat" in SEED_CROPS and "Berry" not in SEED_CROPS and "Wild_Grass" not in SEED_CROPS, SEED_CROPS
# bars: Ore_<Metal>_<Rock> ore BLOCKS (an id with a rock part) -> Ingredient_Bar_<Metal>
ORE_METALS = sorted(set(i.split("_")[1] for i in ITEM_IDS if i.startswith("Ore_") and i.count("_") >= 2))
BAR_METALS = [m for m in ORE_METALS if "Ingredient_Bar_" + m in ITEM_IDS]
