def jstr(xs): return "new String[] { " + ", ".join(json.dumps(x) for x in xs) + " }"
def jint(xs): return "new int[] { " + ", ".join(str(int(x)) for x in xs) + " }"
def jlong(xs): return "new long[] { " + ", ".join("%dL" % x for x in xs) + " }"
def jdbl(xs): return "new double[] { " + ", ".join(repr(float(x)) for x in xs) + " }"
def jbool(xs): return "new boolean[] { " + ", ".join("true" if x else "false" for x in xs) + " }"

# ================= 0.2.3 swing speed assets (research/Swing-Speed-Spec.md 2.3 + 3.7) =================
# Generated from Assets.zip read IN MEMORY (read-only); only our own JSON goes into the jar, no vanilla file is copied into the repo.
# Every self-check below fails the build (SystemExit) when a Hytale update changed what this design relies on.
SWING_MAX = 40          # tiers +1 % .. +40 %; +40 % = 0.25 s = the vanilla swing length = back-to-back swings (the ceiling)
SWING_BASE = 0.35       # InteractionTypeUtils.getDefaultCooldown(Primary) - self-check 3 re-reads it from the server jar
SWING_EFFECT = {"Duration": 3, "OverlapBehavior": "Overwrite"}   # hidden marker: no icon, no ApplicationEffects, no stats
# (family, vanilla root id = vanilla Interaction id = cooldown id, vanilla tool item, vanilla swing interaction, root path in Assets.zip)
SWING_FAMS = [("Mine", "Pickaxe_Attack", "Tool_Pickaxe_Crude", "Pickaxe_Mine", "Server/Item/RootInteractions/Weapons/Pickaxe/Variants/Pickaxe_Attack.json"),
              ("Chop", "Hatchet_Attack", "Tool_Hatchet_Crude", "Hatchet_Chop", "Server/Item/RootInteractions/Weapons/Hatchet/Variants/Hatchet_Attack.json")]
def swing_id(fam, k): return "Skyy_Tree_Swing_%s_%02d" % (fam, k)
def swing_tree_id(fam): return "Skyy_Tree_Swing_" + fam
SWING_CD = [SWING_BASE] + [round(SWING_BASE / (1.0 + k / 100.0), 4) for k in range(1, SWING_MAX + 1)]
assert SWING_CD[25] == 0.28 and SWING_CD[40] == 0.25 and SWING_CD[5] == 0.3333 and SWING_CD[1] == 0.3465
assert all(SWING_CD[k] < SWING_CD[k - 1] for k in range(1, SWING_MAX + 1))
def swing_tree(fam, target):
    ids = [None] + [swing_id(fam, k) for k in range(1, SWING_MAX + 1)]
    def leaf(k):
        return {"Type": "TriggerCooldown", "Cooldown": {"Id": target, "Cooldown": SWING_CD[k]}, "Next": target}
    def split(lo, hi):
        if lo == hi: return leaf(lo)
        mid = (lo + hi + 1) // 2
        return {"Type": "EffectCondition", "Match": "None", "EntityEffectIds": ids[mid:hi + 1], "Next": split(lo, mid - 1), "Failed": split(mid, hi)}
    return {"Type": "EffectCondition", "Match": "None", "EntityEffectIds": ids[1:], "Next": target, "Failed": split(1, SWING_MAX)}
SWING_FILES = {}
with zipfile.ZipFile(ASSETS) as _z:
    _names = _z.namelist()
    def _ids(prefix):
        out = {}
        for n in _names:
            if n.startswith(prefix) and n.endswith(".json"):
                out.setdefault(os.path.basename(n)[:-5], []).append(n)
        return out
    def _rd(path): return json.loads(_z.read(path).decode("utf-8-sig"))
    V_EFF, V_INT, V_ROOT, V_ITEM = (_ids("Server/Entity/Effects/"), _ids("Server/Item/Interactions/"), _ids("Server/Item/RootInteractions/"),
                                    _ids("Server/Item/Items/"))
    def _one(m, i, what):
        if i not in m: raise SystemExit("swing self-check: vanilla %s %s is missing" % (what, i))
        if len(m[i]) != 1: raise SystemExit("swing self-check: vanilla %s %s exists %d times: %s" % (what, i, len(m[i]), m[i]))
        return m[i][0]
    # swing length = RunTime + longest Parallel branch + the longest of Next / Failed / a Selector's hit chains, following string ids and
    # Replace defaults (a list of interactions runs one after the other). Pickaxe_Mine: 0.083 + max(0.05 + break, 0.083 + max(0.084,
    # hit 0), 0.167) = 0.25. CONSERVATIVE on purpose: the 2nd+ Parallel branches and a Selector's HitEntity / HitEntityRules[].Next /
    # HitBlock chains are FORKED chains (ParallelInteraction.tick0 / SelectInteraction.tick0 -> InteractionContext.fork, bytecode
    # 2026-09-25), counted as if they kept the swing busy; a hit chain forks while the Selector runs, so it ends at most RunTime + its
    # own length after that step starts (the same slot as Next).
    # a root-valued field (Parallel branch, Replace default, Selector hit chain): inline {"Interactions": [...]} or a RootInteraction id
    def _root(r, depth):
        if r is None: return 0.0
        if isinstance(r, str): return _dur(_rd(_one(V_ROOT, r, "root interaction")).get("Interactions"), depth + 1)
        if not isinstance(r, dict): raise SystemExit("swing self-check: unexpected root interaction value %r" % (r,))
        return _dur(r.get("Interactions"), depth + 1)
    def _dur(x, depth=0):
        if depth > 40: raise SystemExit("swing self-check: interaction nesting too deep near %r" % (x,))
        if x is None: return 0.0
        if isinstance(x, str): return _dur(_rd(_one(V_INT, x, "interaction")), depth + 1)
        if isinstance(x, list): return sum(_dur(e, depth + 1) for e in x)
        if not isinstance(x, dict): raise SystemExit("swing self-check: unexpected interaction node %r" % (x,))
        typ = x.get("Type")
        if typ == "Chaining": raise SystemExit("swing self-check: a Chaining step inside the swing - the swing-length check needs a look")
        if x.get("WaitForAnimationToFinish"): raise SystemExit("swing self-check: a WaitForAnimationToFinish step - the swing length now follows the animation")
        t = float(x.get("RunTime", 0) or 0)
        if typ == "Parallel": t += max(_root(b, depth + 1) for b in x["Interactions"])
        elif typ == "Replace": t += _root(x.get("DefaultValue"), depth + 1)
        tail = [_dur(x.get("Next"), depth + 1), _dur(x.get("Failed"), depth + 1)]
        if typ == "Selector":
            tail.append(_root(x.get("HitEntity"), depth + 1))
            tail.append(_root(x.get("HitBlock"), depth + 1))
            for _r in (x.get("HitEntityRules") or []):
                if not isinstance(_r, dict): raise SystemExit("swing self-check: unexpected HitEntityRules entry %r" % (_r,))
                tail.append(_root(_r.get("Next"), depth + 1))
        return t + max(tail)
    for fam, root, tool, swing, rpath in SWING_FAMS:
        tid = swing_tree_id(fam)
        # check 1: the vanilla root, interaction and tool this build overrides / points at
        if _one(V_ROOT, root, "root interaction") != rpath: raise SystemExit("swing self-check: root %s moved: %s" % (root, V_ROOT[root]))
        if _rd(rpath) != {"Interactions": [root]}:
            raise SystemExit("swing self-check: vanilla root %s is no longer exactly {\"Interactions\": [\"%s\"]} (no Cooldown): %s" % (root, root, json.dumps(_rd(rpath))))
        _vi = _rd(_one(V_INT, root, "interaction"))
        if _vi.get("Type") != "Chaining" or _vi.get("Next") != [swing]:
            raise SystemExit("swing self-check: vanilla interaction %s no longer chains into %s: %s" % (root, swing, json.dumps(_vi)))
        _ti = _rd(_one(V_ITEM, tool, "item"))
        if (_ti.get("Interactions") or {}).get("Primary") != root:
            raise SystemExit("swing self-check: %s no longer uses the Primary root %s: %s" % (tool, root, json.dumps(_ti.get("Interactions"))))
        # check 2: no tier cooldown is shorter than the vanilla swing
        _len = _dur(swing)
        if _len > 0.25 + 1e-9: raise SystemExit("swing self-check: %s now lasts %.4f s (> 0.25 s) - the +%d%% tier would cut into the swing" % (swing, _len, SWING_MAX))
        if min(SWING_CD) < _len - 1e-9: raise SystemExit("swing self-check: a tier cooldown (%.4f s) is shorter than the %s swing (%.4f s)" % (min(SWING_CD), swing, _len))
        # check 5 (collisions): our ids are new; only the root is an intended override (same path, same id)
        for k in range(1, SWING_MAX + 1):
            if swing_id(fam, k) in V_EFF: raise SystemExit("swing self-check: vanilla already has an effect " + swing_id(fam, k))
        if tid in V_INT or tid in V_ROOT or tid in V_EFF: raise SystemExit("swing self-check: vanilla already has an asset " + tid)
        tree = swing_tree(fam, root)
        # check 4: walk the generated tree for every tier (EffectCondition Match None fails when ANY listed effect is active)
        def _walk(node, have):
            depth = 0
            while isinstance(node, dict) and node["Type"] == "EffectCondition":
                assert node["Match"] == "None" and node["EntityEffectIds"], node
                node = node["Failed"] if any(e in have for e in node["EntityEffectIds"]) else node["Next"]
                depth += 1
            return node, depth
        _deep = 0
        for k in range(0, SWING_MAX + 1):
            got, d = _walk(tree, set([swing_id(fam, k)]) if k else set())
            _deep = max(_deep, d)
            if k == 0:
                if got != root: raise SystemExit("swing self-check: tier 0 does not reach the vanilla %s: %r" % (root, got))
            elif not (isinstance(got, dict) and got["Type"] == "TriggerCooldown" and got["Next"] == root and got["Cooldown"]["Id"] == root
                      and got["Cooldown"]["Cooldown"] == SWING_CD[k]):
                raise SystemExit("swing self-check: tier %d reaches %r" % (k, got))
        assert _deep == 7, _deep   # top node + 6 split levels
        # check 5 (references): every EffectCondition id is one of ours, every string Next is the vanilla interaction
        def _refs(node, effs, nexts):
            if isinstance(node, str): nexts.add(node); return
            for e in node.get("EntityEffectIds", []): effs.add(e)
            for key in ("Next", "Failed"):
                if key in node: _refs(node[key], effs, nexts)
        _effs, _nexts = set(), set()
        _refs(tree, _effs, _nexts)
        assert _effs == set(swing_id(fam, k) for k in range(1, SWING_MAX + 1)) and _nexts == set([root]) and root in V_INT
        for k in range(1, SWING_MAX + 1):
            SWING_FILES["Server/Entity/Effects/SkyyTrees/%s.json" % swing_id(fam, k)] = json.dumps(SWING_EFFECT, indent=2)
        SWING_FILES["Server/Item/Interactions/SkyyTrees/%s.json" % tid] = json.dumps(tree, indent=2)
        SWING_FILES[rpath] = json.dumps({"Interactions": [tid]}, indent=2)
    # ---- 0.2.4 HARD RULE (Skyy 2026-09-25, OPEN-QUESTIONS "Swing speed"): the hatchet bonus only when the swing chops WOOD ----
    # 0.2.3 shortened the cooldown at the START of every hatchet swing, so mob hits came faster too. 0.2.4 decides at the moment the swing
    # breaks its block: a GENERATED copy of the vanilla swing (Skyy_Tree_Chop = Hatchet_Chop with its one block-break step pointed at
    # Skyy_Tree_Chop_Wood) runs a BlockCondition on the block the swing hits (UseLatestTarget like vanilla BreakBlock; wood tags) at
    # T_HIT (0.083 + 0.05 = 0.133 s): wood -> TriggerCooldown (tier period - T_HIT), anything else (air / a mob only / stone / furniture)
    # -> TriggerCooldown (0.35 - T_HIT) = exactly the vanilla cadence; then the vanilla Block_Break. A tier player's swing first resets the
    # cooldown to the vanilla 0.35 (so nothing from a fast wood swing carries into the next swing); players without a chop tier take the
    # vanilla Interaction Hatchet_Attack untouched. Only our own JSON goes into the jar (generated from Assets.zip read in memory).
    import copy as _copy
    CHOP_IDS = [swing_id("Chop", k) for k in range(1, SWING_MAX + 1)]
    CHOP_NEW = ["Skyy_Tree_Chop_Chain", "Skyy_Tree_Chop", "Skyy_Tree_Chop_Wood"]
    _ha = _rd(_one(V_INT, "Hatchet_Attack", "interaction"))
    _hc = _rd(_one(V_INT, "Hatchet_Chop", "interaction"))
    _one(V_INT, "Block_Break", "interaction")
    if sorted(_ha) != ["ChainingAllowance", "Next", "Type"] or _ha["Type"] != "Chaining" or _ha["Next"] != ["Hatchet_Chop"]:
        raise SystemExit("chop self-check: vanilla Hatchet_Attack is no longer {Chaining, ChainingAllowance, Next [Hatchet_Chop]}: " + json.dumps(_ha))
    _nx = _hc.get("Next")
    if _hc.get("Type") != "Simple" or not isinstance(_nx, dict) or _nx.get("Type") != "Parallel" or not isinstance(_nx.get("Interactions"), list):
        raise SystemExit("chop self-check: vanilla Hatchet_Chop is no longer Simple -> Parallel: " + json.dumps(_hc)[:300])
    def _isblk(b):
        return (isinstance(b, dict) and isinstance(b.get("Interactions"), list) and len(b["Interactions"]) == 1
                and isinstance(b["Interactions"][0], dict) and b["Interactions"][0].get("Next") == "Block_Break")
    _blk = [b for b in _nx["Interactions"] if _isblk(b)]
    if len(_blk) != 1:
        raise SystemExit("chop self-check: Hatchet_Chop no longer has exactly one [Simple -> Block_Break] branch: " + json.dumps(_nx)[:400])
    _st = _blk[0]["Interactions"][0]
    if _st.get("Type") != "Simple" or set(_st) - set(["Type", "$Comment", "RunTime", "Next"]):
        raise SystemExit("chop self-check: the block-break step of Hatchet_Chop changed: " + json.dumps(_st))
    if json.dumps(_hc).count('"Block_Break"') != 1:
        raise SystemExit("chop self-check: Hatchet_Chop names Block_Break more than once - the wood check must sit in front of its only block break")
    T_HIT = round(float(_hc.get("RunTime", 0) or 0) + float(_st.get("RunTime", 0) or 0), 4)
    if not (0.0 < T_HIT <= min(SWING_CD) - 0.05):
        raise SystemExit("chop self-check: the block break now happens %.4f s into the swing - no room for the tier cooldowns" % T_HIT)
    CHOP_CD = [round(SWING_CD[k] - T_HIT, 4) for k in range(0, SWING_MAX + 1)]
    assert all(c >= 0.05 for c in CHOP_CD) and all(abs(T_HIT + CHOP_CD[k] - SWING_CD[k]) < 0.00011 for k in range(SWING_MAX + 1)), CHOP_CD
    assert all(T_HIT + c >= _dur("Hatchet_Chop") - 1e-9 for c in CHOP_CD)   # never a next swing while this one still runs
    # the tags AssetExtraInfo$Data.putTags builds from an item's "Tags": {"Type": ["Wood", "Trunk"], ...} (key, value and key=value)
    CHOP_TAGS = ["Type=Wood", "Type=Trunk", "Type=Branch", "Type=Tree", "BranchType=Long", "BranchType=Short", "BranchType=Corner"]
    # every natural trunk and branch must match: by a tag (its own "Tags", else the Parent's - whether the engine MERGES a child's Tags
    # with the Parent's is not verified, so the strict reading is used), else by an explicit Id matcher (e.g. Wood_Apple_Branch_Long and
    # Wood_Ice_Branch_Long list only their Family tag)
    def _tags(i, depth=0):
        if i not in V_ITEM or depth > 20: return {}
        _d = _rd(V_ITEM[i][0])
        if isinstance(_d.get("Tags"), dict): return _d["Tags"]
        return _tags(_d.get("Parent"), depth + 1) if _d.get("Parent") else {}
    def _hit(tg):
        return bool(set("%s=%s" % (kk, v) for kk, vv in tg.items() for v in (vv if isinstance(vv, list) else [])) & set(CHOP_TAGS))
    _trunks = sorted(i for i in V_ITEM if re.match(r"^Wood_[A-Za-z_]+_Trunk(_Full)?$", i))
    _branches = sorted(i for i in V_ITEM if re.match(r"^Wood_[A-Za-z_]+_Branch_(Long|Short|Corner)$", i))
    CHOP_IDS_EXTRA = [i for i in _trunks + _branches if not _hit(_tags(i))]
    if len(_trunks) < 60 or len(_branches) < 60 or len(CHOP_IDS_EXTRA) > 12:
        raise SystemExit("chop self-check: natural wood without a matcher tag (%d trunks, %d branches): %s" % (len(_trunks), len(_branches), CHOP_IDS_EXTRA))
    CHOP_COVER = (len(_trunks), len(_branches), len(CHOP_IDS_EXTRA))
    def _cd(c, nxt): return {"Type": "TriggerCooldown", "Cooldown": {"Id": "Hatchet_Attack", "Cooldown": c}, "Next": nxt}
    def _csplit(lo, hi):
        if lo == hi: return _cd(CHOP_CD[lo], "Block_Break")
        mid = (lo + hi + 1) // 2
        return {"Type": "EffectCondition", "Match": "None", "EntityEffectIds": CHOP_IDS[mid - 1:hi], "Next": _csplit(lo, mid - 1), "Failed": _csplit(mid, hi)}
    chop_start = {"Type": "EffectCondition", "Match": "None", "EntityEffectIds": list(CHOP_IDS), "Next": "Hatchet_Attack",
                  "Failed": _cd(SWING_BASE, "Skyy_Tree_Chop_Chain")}
    chop_chain = {"Type": "Chaining", "ChainingAllowance": _ha["ChainingAllowance"], "Next": ["Skyy_Tree_Chop"]}
    chop_swing = _copy.deepcopy(_hc)
    _cb = [b for b in chop_swing["Next"]["Interactions"] if _isblk(b)]
    assert len(_cb) == 1
    _cb[0]["Interactions"][0]["Next"] = "Skyy_Tree_Chop_Wood"
    chop_wood = {"Type": "BlockCondition", "UseLatestTarget": True, "Matchers": [{"Block": {"Tag": t}} for t in CHOP_TAGS] + [{"Block": {"Id": i}} for i in CHOP_IDS_EXTRA],
                 "Next": {"Type": "EffectCondition", "Match": "None", "EntityEffectIds": list(CHOP_IDS),
                          "Next": _cd(CHOP_CD[0], "Block_Break"), "Failed": _csplit(1, SWING_MAX)},
                 "Failed": _cd(CHOP_CD[0], "Block_Break")}
    # the copy differs from vanilla in exactly that one Next
    if json.dumps(chop_swing).replace('"Skyy_Tree_Chop_Wood"', '"Block_Break"') != json.dumps(_hc) or json.dumps(chop_swing).count("Skyy_Tree_Chop_Wood") != 1:
        raise SystemExit("chop self-check: the generated swing differs from vanilla Hatchet_Chop in more than its block-break Next")
    # walk every tier through the start node and the wood node (EffectCondition Match None fails when ANY listed effect is active)
    def _cwalk(node, have):
        while isinstance(node, dict) and node.get("Type") == "EffectCondition":
            node = node["Failed"] if any(e in have for e in node["EntityEffectIds"]) else node["Next"]
        return node
    for k in range(0, SWING_MAX + 1):
        _have = set([CHOP_IDS[k - 1]]) if k else set()
        _s0 = _cwalk(chop_start, _have)
        if k == 0:
            if _s0 != "Hatchet_Attack": raise SystemExit("chop self-check: tier 0 does not reach the vanilla Hatchet_Attack: %r" % (_s0,))
        elif not (isinstance(_s0, dict) and _s0["Type"] == "TriggerCooldown" and _s0["Cooldown"] == {"Id": "Hatchet_Attack", "Cooldown": SWING_BASE}
                  and _s0["Next"] == "Skyy_Tree_Chop_Chain"):
            raise SystemExit("chop self-check: tier %d start reaches %r" % (k, _s0))
        _w = _cwalk(chop_wood["Next"], _have)
        if not (isinstance(_w, dict) and _w["Type"] == "TriggerCooldown" and _w["Next"] == "Block_Break" and _w["Cooldown"]["Id"] == "Hatchet_Attack"
                and _w["Cooldown"]["Cooldown"] == CHOP_CD[k]):
            raise SystemExit("chop self-check: tier %d on wood reaches %r" % (k, _w))
    assert chop_wood["Failed"] == _cd(CHOP_CD[0], "Block_Break") and CHOP_CD[0] == round(SWING_BASE - T_HIT, 4)
    for _i in CHOP_NEW:
        if _i in V_INT or _i in V_ROOT or _i in V_EFF: raise SystemExit("chop self-check: vanilla already has an asset " + _i)
    SWING_FILES["Server/Item/Interactions/SkyyTrees/%s.json" % swing_tree_id("Chop")] = json.dumps(chop_start, indent=2)   # replaces the 0.2.3 tree
    SWING_FILES["Server/Item/Interactions/SkyyTrees/Skyy_Tree_Chop_Chain.json"] = json.dumps(chop_chain, indent=2)
    SWING_FILES["Server/Item/Interactions/SkyyTrees/Skyy_Tree_Chop.json"] = json.dumps(chop_swing, indent=2)
    SWING_FILES["Server/Item/Interactions/SkyyTrees/Skyy_Tree_Chop_Wood.json"] = json.dumps(chop_wood, indent=2)
assert len(SWING_FILES) == 2 * SWING_MAX + 4 + 3   # 0.2.4: + the chop chain, swing copy and wood check
# ---- 0.3.4 LOG FIX (Skyy's 2026-10-09 server log: 'Missing interaction **Skyy_Tree_Chop_Wood_Next_Next' / '_Next_Failed'): NO INLINE STEPS.
# The engine builds a batch's client packet (InteractionPacketGenerator -> configurePacket -> Interaction.getInteractionIdOrUnknown) before
# it loads that batch's inline children (AssetStore.loadAssets0: handleRemoveOrUpdate, then loadContainedAssets), so an inline step's
# engine name ('*'-prefixed) is "missing" for a moment (WARN + a Hytale:Hytale SendMessage placeholder, then the real step loads over it;
# the SkyySkills 0.4.23 roll fix). Every SkyyTrees interaction file is flattened here: each inline INTERACTION becomes its own named file in
# Server/Item/Interactions/SkyyTrees/ (this jar's one Interactions batch). Inline ROOTS (Parallel branches, Replace defaults, Selector hit
# chains) stay inline objects; the interactions inside them are named. Re-inlined, every file is exactly 0.3.3's (asserted below).
SWING_FILES_033 = dict(SWING_FILES)          # the 0.3.3 shapes (inline) - kept only for the checks
SWING_FLAT = {}                              # name -> body of every NEW named step (0.3.4)
_FLAT_TOPS = sorted(os.path.basename(_p)[:-5] for _p in SWING_FILES if _p.startswith("Server/Item/Interactions/"))
assert _FLAT_TOPS == sorted([swing_tree_id("Mine"), swing_tree_id("Chop")] + CHOP_NEW), _FLAT_TOPS
_TIER_RE = re.compile(r"^Skyy_Tree_Swing_(Mine|Chop)_(\d\d)$")
def _islots(x):
    """the interaction-valued places of one interaction body: (container, key, name token). Next / Failed (a Chaining's Next is a list);
    the interactions inside the inline roots of a Parallel branch, a Replace default and a Selector's HitEntity / HitBlock / rule Next"""
    out = []
    for _k, _tk in (("Next", "N"), ("Failed", "F")):
        _v = x.get(_k)
        if isinstance(_v, list): out += [(_v, _i, "%s%d" % (_tk, _i)) for _i in range(len(_v))]
        elif _v is not None: out.append((x, _k, _tk))
    _roots = []
    if x.get("Type") == "Parallel": _roots += [(x["Interactions"], _j, "P%d" % _j) for _j in range(len(x["Interactions"]))]
    if x.get("Type") == "Replace" and "DefaultValue" in x: _roots.append((x, "DefaultValue", "D"))
    if x.get("Type") == "Selector":
        _roots += [(x, _k, _tk) for _k, _tk in (("HitEntity", "HE"), ("HitBlock", "HB")) if _k in x]
        _roots += [(_r, "Next", "HR%d" % _ri) for _ri, _r in enumerate(x.get("HitEntityRules") or []) if "Next" in _r]
    for _c, _k, _tk in _roots:
        _rv = _c[_k]
        if isinstance(_rv, dict):
            _l = _rv.get("Interactions") or []
            out += [(_l, _i, _tk if len(_l) == 1 else "%s_%d" % (_tk, _i)) for _i in range(len(_l))]
    return out
def _flat_name(top, node, fallback):
    """tier-tree steps by meaning, the rest by place"""
    _t = node.get("Type")
    if _t == "EffectCondition":
        _m = [_TIER_RE.match(_e) for _e in node.get("EntityEffectIds", [])]
        if _m and all(_m):
            _ks = [int(_x.group(2)) for _x in _m]
            assert _ks == list(range(_ks[0], _ks[-1] + 1)), (top, _ks)
            return "%s_If_%02d_%02d" % (top, _ks[0], _ks[-1])
    if _t == "TriggerCooldown" and sorted(node) == ["Cooldown", "Next", "Type"]:
        _cd, _nx = node["Cooldown"]["Cooldown"], node["Next"]
        if top == swing_tree_id("Mine") and _nx == "Pickaxe_Attack" and _cd in SWING_CD: return "%s_Tier_%02d" % (top, SWING_CD.index(_cd))
        if top == "Skyy_Tree_Chop_Wood" and _nx == "Block_Break" and _cd in CHOP_CD: return "%s_Tier_%02d" % (top, CHOP_CD.index(_cd))
        if top == swing_tree_id("Chop") and _nx == "Skyy_Tree_Chop_Chain" and _cd == SWING_BASE: return top + "_Reset"
    return fallback
def _flatten(top, body, here):
    for _c, _k, _tk in _islots(body):
        _v = _c[_k]
        if isinstance(_v, dict):
            # the wood check's "not wood" leaf has the same body as tier 0 - its own file, so every 0.3.3 step stays exactly one step
            _nm = top + "_NotWood" if (top == "Skyy_Tree_Chop_Wood" and here == top and _tk == "F") else _flat_name(top, _v, here + "_" + _tk)
            _child = _copy.deepcopy(_v)
            _flatten(top, _child, _nm)
            assert _nm not in SWING_FLAT and _nm not in _FLAT_TOPS, "0.3.4: the name %s would be used twice" % _nm
            SWING_FLAT[_nm] = _child
            _c[_k] = _nm
def _reinline(body):
    """a flattened body with every NEW name put back inline (the 0.3.3 shape)"""
    _b = _copy.deepcopy(body)
    for _c, _k, _tk in _islots(_b):
        if isinstance(_c[_k], str) and _c[_k] in SWING_FLAT:
            _c[_k] = _reinline(SWING_FLAT[_c[_k]])
    return _b
def _has_inline(x, top=True):
    """True when anything below the top is an inline interaction object (a dict with a Type)"""
    if isinstance(x, dict):
        if not top and "Type" in x: return True
        return any(_has_inline(_v, False) for _v in x.values())
    if isinstance(x, list): return any(_has_inline(_v, False) for _v in x)
    return False
_FLAT_BODY = {}
for _top in _FLAT_TOPS:
    _p = "Server/Item/Interactions/SkyyTrees/%s.json" % _top
    _b = json.loads(SWING_FILES[_p])
    _flatten(_top, _b, _top)
    _FLAT_BODY[_top] = _b
for _top in _FLAT_TOPS:
    _p = "Server/Item/Interactions/SkyyTrees/%s.json" % _top
    if json.dumps(_reinline(_FLAT_BODY[_top]), indent=2) != SWING_FILES_033[_p]:
        raise SystemExit("0.3.4 flatten: %s re-inlined is not 0.3.3's file" % _top)
    SWING_FILES[_p] = json.dumps(_FLAT_BODY[_top], indent=2)
for _nm in sorted(SWING_FLAT):
    SWING_FILES["Server/Item/Interactions/SkyyTrees/%s.json" % _nm] = json.dumps(SWING_FLAT[_nm], indent=2)
# the checks: nothing inline left; every name a step uses is ours or vanilla; no new id is a vanilla id (any asset type); no Parallel with
# < 2 branches (the engine's validator: "Array size" - what once stopped the server); the expected file set
_FLAT_ALL = dict((_t, _FLAT_BODY[_t]) for _t in _FLAT_TOPS)
_FLAT_ALL.update(SWING_FLAT)
assert not [_n for _n, _b in _FLAT_ALL.items() if _has_inline(_b)], "0.3.4: an inline step is left"
for _n, _b in _FLAT_ALL.items():
    for _c, _k, _tk in _islots(_b):
        _r = _c[_k]
        assert isinstance(_r, str) and (_r in _FLAT_ALL or _r in V_INT), "0.3.4: %s names %r - neither ours nor vanilla" % (_n, _r)
    assert _b.get("Type") != "Parallel" or len(_b["Interactions"]) >= 2, "0.3.4: a Parallel with fewer than 2 branches: " + _n
for _n in SWING_FLAT:
    if _n in V_INT or _n in V_ROOT or _n in V_EFF or _n in V_ITEM: raise SystemExit("0.3.4 flatten: vanilla already has an asset " + _n)
    assert re.match(r"^Skyy_Tree_[A-Za-z0-9_]+$", _n) and not _n.startswith("*"), _n
def _fam(n): return max([_t for _t in _FLAT_TOPS if n.startswith(_t + "_")], key=len)   # the file a named step came from
_FLAT_N = dict((_t, len([_n for _n in SWING_FLAT if _fam(_n) == _t])) for _t in _FLAT_TOPS)
assert _FLAT_N[swing_tree_id("Mine")] == 2 * SWING_MAX - 1, _FLAT_N                     # 39 splits + 40 tier leaves
assert _FLAT_N["Skyy_Tree_Chop_Wood"] == 2 * SWING_MAX + 2 and _FLAT_N["Skyy_Tree_Chop"] == 6 and _FLAT_N["Skyy_Tree_Chop_Chain"] == 0, _FLAT_N
assert _FLAT_N[swing_tree_id("Chop")] == 1 and sum(_FLAT_N.values()) == len(SWING_FLAT), _FLAT_N   # Wood: If_01_40 + 39 + Tier_00..40 + NotWood
assert SWING_FLAT["Skyy_Tree_Chop_Wood_NotWood"] == SWING_FLAT["Skyy_Tree_Chop_Wood_Tier_00"] == {"Type": "TriggerCooldown", "Cooldown": {"Id": "Hatchet_Attack", "Cooldown": CHOP_CD[0]}, "Next": "Block_Break"}
assert _FLAT_BODY["Skyy_Tree_Chop_Wood"]["Failed"] == "Skyy_Tree_Chop_Wood_NotWood" and SWING_FLAT["Skyy_Tree_Chop_Wood_If_01_40"]["Next"] == "Skyy_Tree_Chop_Wood_Tier_00"
assert swing_tree_id("Chop") + "_Reset" in SWING_FLAT and "Skyy_Tree_Chop_Wood_Tier_00" in SWING_FLAT and "Skyy_Tree_Chop_Wood_If_01_40" in SWING_FLAT
assert SWING_FLAT["Skyy_Tree_Chop_N_P1"]["Next"] == "Skyy_Tree_Chop_Wood" and SWING_FLAT["Skyy_Tree_Chop_N"]["Type"] == "Parallel"
assert all(SWING_FLAT["Skyy_Tree_Chop_Wood_Tier_%02d" % _k]["Cooldown"]["Cooldown"] == CHOP_CD[_k] for _k in range(SWING_MAX + 1))
assert all(SWING_FLAT["%s_Tier_%02d" % (swing_tree_id("Mine"), _k)]["Cooldown"]["Cooldown"] == SWING_CD[_k] for _k in range(1, SWING_MAX + 1))
assert set(SWING_FILES_033) <= set(SWING_FILES) and len(SWING_FILES) == len(SWING_FILES_033) + len(SWING_FLAT)
assert all(SWING_FILES[_p] == SWING_FILES_033[_p] for _p in SWING_FILES_033 if not _p.startswith("Server/Item/Interactions/"))
print("0.3.4 named steps: %d interaction files -> %d (+%d named steps: %s), re-inlined = 0.3.3, no inline step, every name resolves"
      % (len(_FLAT_TOPS), len(_FLAT_TOPS) + len(SWING_FLAT), len(SWING_FLAT), ", ".join("%s %d" % (_t, _FLAT_N[_t]) for _t in _FLAT_TOPS)))
for _p, _t in SWING_FILES.items():
    assert json.loads(_t) is not None and all(ord(ch) < 128 for ch in _t) and _p.startswith("Server/"), _p
# check 3: the base the tier numbers are computed from - InteractionTypeUtils.getDefaultCooldown still returns (ldc) float 0.35
import jpype as _jp
_IP = _jp.JClass("javassist.bytecode.InstructionPrinter")
_bos = _jp.JClass("java.io.ByteArrayOutputStream")()
_ITU = pool.get("com.hypixel.hytale.server.core.modules.interaction.interaction.config.InteractionTypeUtils")
_IP(_jp.JClass("java.io.PrintStream")(_bos)).print_(_ITU.getDeclaredMethod("getDefaultCooldown"))
_gdc = str(_bos.toString())
if not re.search(r"ldc(_w)? #\d+ = float 0\.35\b", _gdc):
    raise SystemExit("swing self-check: InteractionTypeUtils.getDefaultCooldown no longer loads float 0.35 - every tier number would be wrong:\n" + _gdc)
# 0.2.4 chop check: the engine still has what the generated chop chain uses (BlockCondition tag matchers, SimpleBlockInteraction
# UseLatestTarget - BlockConditionInteraction's codec builds on SimpleBlockInteraction.CODEC, bytecode 2026-09-28)
_CFGC = "com.hypixel.hytale.server.core.modules.interaction.interaction.config.client."
for _c, _f in (("BlockConditionInteraction$BlockIdMatcher", "tag"), ("BlockConditionInteraction$BlockIdMatcher", "tagIndex"),
               ("BlockConditionInteraction", "matchers"), ("SimpleBlockInteraction", "useLatestTarget"), ("TriggerCooldownInteraction", "cooldown")):
    try: pool.get(_CFGC + _c).getDeclaredField(_f)
    except Exception: raise SystemExit("chop self-check: %s.%s is gone - the wood-only hatchet chain needs a look" % (_c, _f))
print("chop: hatchet bonus only on wood - block break at %.3f s, wood tiers %.4f..%.4f s after it, vanilla rest %.4f s, %d trunks + %d branches (%d by id)"
      % (T_HIT, CHOP_CD[SWING_MAX], CHOP_CD[1], CHOP_CD[0], CHOP_COVER[0], CHOP_COVER[1], CHOP_COVER[2]))

# ================= 0.3 PART 2: the class tree template (research/Skill-Trees-2-Spec.md 5-7, Skyy's answers 1-5 + 7) =================
# 0.3.3 (2026-10-07, research/cloud/Class-Tree-Build-Map.md + Class-Tree-Paths.md): page 1 is the live 0.3.2 page (stat spine + rune
# slots); page 2's three stat lanes became the TRUNK T1-T6 + THREE LOCKED PATHS PA / PB / PC (5 nodes each, the first owned path node picks
# the path) + the elements LE / CE / RE after N5 + the Priest switch TS; Assassin and Monk have trees. A node: (id, AP, parents (any one),
# need, lock (the pick-one twin), lane (0 none, 1 path A, 2 path B, 3 path C), lane count needed, page, row, col, role). Roles: 0 spine
# stat, 1 pick-one passive, 2 ability rune slot, 3 / 4 modifier rune slots, 5 trunk node, 6 path node, 7 element (coming later), 9 switch.
CLASSES = ["Archer", "Warrior", "Mage", "Berserker", "Priest", "Assassin", "Monk", "Spellblade"]   # 0.3.3: + Assassin, Monk (SkyyClasses 0.1.14); 0.3.10: + Spellblade (SkyyClasses 0.1.25)
CSKILL = ["Archery", "Swordsmanship", "Sorcery", "Fury", "Divinity", "Assassination", "Zen", "Battlemagic"]   # 0.3.5: what players see (Monk = Zen, LOCKED 2026-10-08)
# 0.3.5: the skill:fn:level names = 0.3.4's CSKILL exactly (SkyySkills 0.4.21-0.4.26 know "Discipline" as the Monk label, 0.4.27+ as its alias)
CSKILL_KEY = ["Archery", "Swordsmanship", "Sorcery", "Fury", "Divinity", "Assassination", "Discipline", "Battlemagic"]
assert [a for a, b in zip(CSKILL, CSKILL_KEY) if a != b] == ["Zen"]
