C_MODNAME = {'Power': 'Power+', 'Radius': 'Radius+', 'Duration': 'Duration+', 'Efficiency': 'Efficiency', 'Split': 'Split', 'Pierce': 'Pierce', 'Chain': 'Chain', 'Lingering': 'Lingering', 'Slow': 'Slow', 'Knockback': 'Knockback+', 'Follow': 'Follow', 'Ward': 'Ward', 'Echo': 'Echo', 'Ricochet': 'Ricochet', 'Haste': 'Haste', 'Pull': 'Pull', 'Leech': 'Leech', 'Floor': 'Floor', 'Seeker': 'Seeker'}   # 0.3.13: SkyyClasses' modifier display names
C_NOUNS = ['First Strike damage', 'HP per Mana', 'Health on a save', 'arrow damage', 'blast damage', 'boss multiplier', 'bubble HP', 'buff', 'buff per stack', 'counter damage', 'damage', 'damage + Breach', 'damage + Weaken', 'damage buff', 'damage cut', 'damage per stack', 'element damage', 'heal', 'poison damage', 'rift Breach', 'shockwave damage', 'smoke', 'speed per stack']   # fix round 2: SkyyClasses' level-gain nouns (the focus view's text-fit asserts)
assert set(MOD_DESC) == set(C_MODNAME) == set(MOD_ICON), "every modifier has a text and an icon"
assert sorted(C_ABILS) == sorted(CLASSES) and all(len(v) == 5 for v in C_ABILS.values())
assert all(len(set(a[2])) == len(a[2]) for v in C_ABILS.values() for a in v if a)   # 0.3.18: no modifier slots in the tree (no slot cap)
# the build cross-checks the baked table against the newest SkyyClasses build script it finds (a later SkyyClasses changed its abilities)
def _cls_check():
    import ast as _ast, glob as _glob
    _cands = sorted(_glob.glob(os.path.join(os.path.dirname(HERE), "SkyyClasses", "build_skyyclasses_0.1.*.py")),
                    key=lambda p: [int(x) for x in re.findall(r"(\d+)", os.path.basename(p))])
    if not _cands: return "no SkyyClasses build script found (not checked)"
    _t = _ast.parse(open(_cands[-1], encoding="utf8").read())
    _l = {}
    for _n in _t.body:
        if isinstance(_n, _ast.Assign) and len(_n.targets) == 1 and isinstance(_n.targets[0], _ast.Name) and _n.targets[0].id in ("ABILS", "AB_MODS", "MODS"):
            _l[_n.targets[0].id] = _ast.literal_eval(_n.value)
    _c = {}
    for _id, _nm, _cl, _ti, _b, _p in _l["ABILS"]:
        _c.setdefault(_cl, [None] * 5)[_ti] = (_id, _nm, list(_l["AB_MODS"][_id]))
    if _c != C_ABILS or dict((m[0], m[1]) for m in _l["MODS"]) != C_MODNAME:
        raise SystemExit("0.3.13: SkyyClasses' abilities / modifiers changed in %s - re-run tools/trees_0_3_13_patch.py with the new table" % os.path.basename(_cands[-1]))
    return "matches " + os.path.basename(_cands[-1])
CLS_CHECK = _cls_check()
def cls_abil(cn, tier): return C_ABILS[cn][tier]
CN = []   # per class x node: dict(kind, amt, name, icon, min, now, how, hid, rk, m2)
for ci, cn in enumerate(CLASSES):
    pnames, picons, trunk, pa, pb, pc = CPATHS[cn][0], CPATHS[cn][1], CPATHS[cn][2], CPATHS[cn][3], CPATHS[cn][4], CPATHS[cn][5]
    assert len(trunk) == 6 and len(pa) == len(pb) == len(pc) == 5, cn
    seen = {}
    for n in CT:
        nid, ap, _par, _need, _lock, lane, _lc, _pg, _r, _c, role = n
        kind, amt, name, icon, mn, now, how, hid = "-", 0, nid, "Deco_Scroll", 0, "", "", False
        abid, modid = "", ""   # 0.3.13: SkyyClasses' ability id / modifier id of an ability or modifier node
        node = None
        if role in (0, 1):
            k, units = CT_SPINE[CMAGIC[ci]][nid]
            kind, amt = k, int(round(UNIT[k] * units))
            if nid == "ROOT": name, icon = "Root", CICON[ci]
            elif role == 1: name, icon = ("Bulwark" if nid == "X2" else ("Wellspring" if CMAGIC[ci] else "Edge")), KIND_ICON[k]
            else:
                seen[k] = seen.get(k, 0) + 1
                name, icon = KIND_WORD[k] + " " + ROMAN[seen[k] - 1], KIND_ICON[k]
        elif role == 5:
            node = trunk[int(nid[1]) - 1]
            mn = TRUNK_LV[int(nid[1]) - 1]
            if cn == "Archer" and nid == "T6": mn = 75          # Class-Tree-Paths 2026-10-06: Holster Reload is Lv 75
        elif role == 6:
            node = (pa, pb, pc)[lane - 1][int(nid[2]) - 1]
            mn = PATH_LV[int(nid[2]) - 1]
        elif role == 9:
            if cn == "Priest": node = CPRIEST_TS
            else: hid, name, now, how = True, "Switch", "", ""
            mn = 1
        elif role == 7:
            pn = pnames[lane - 1]
            name, icon, now, mn = pn + " Element", "Rock_Gem_Ruby", "Element of the " + pn + " path - later (needs SkyyGear elements)", 75
        elif role == 2:   # 0.3.13: an ABILITY node - buying it (class.ap.ability, 1 AP) unlocks the ability; SkyyClasses applies it (kind K)
            kind = "K"
            ab = cls_abil(cn, ABL_TIER[ABL.index(nid)])
            if ab is None:
                hid, name, now, how = True, "Ability", "", ""
            else:
                abid, name, icon = ab[0], ab[1], ABIL_ICON[ABL.index(nid)]
                now = "%s - castable; its modifiers unlock as it levels up" % ab[1]   # 0.3.18
                tw = cls_abil(cn, 7 - ABL_TIER[ABL.index(nid)]) if nid in ("A4a", "A4b") else None
                how = (("Pick one: buying it blocks %s (a respec frees the choice). " % tw[1]) if tw else "") + \
                      "Needs its class level; AP: the Cost line. The ability's level then grows by use and adds power"
        elif role == 3:   # 0.3.13: a MODIFIER node - buying it (class.ap.modifier, 1 AP) unlocks that modifier for that ability at once
            kind = "K"
            pa_ = _par[0]
            k_ = int(nid[len(pa_) + 1:]) - 1
            ab = cls_abil(cn, ABL_TIER[ABL.index(pa_)])
            if ab is None or k_ >= len(ab[2]):
                hid, name, now, how = True, "Modifier", "", ""
            else:
                abid, modid = ab[0], ab[2][k_]
                name, icon = C_MODNAME[modid], MOD_ICON[modid]
                now = "%s for %s - %s" % (C_MODNAME[modid], ab[1], MOD_DESC[modid])
                how = "Needs only %s (AP: the Cost line). Usable at once: click %s under Abilities, then a modifier slot. Its level grows by use" % (ab[1], ab[1])
        else:
            raise SystemExit("0.3.13: unknown class node role %d (%s)" % (role, nid))
        if node is not None:
            name, kind, amt, now, how0, ic0 = node
            icon = ic0 or (picons[lane - 1] if lane else CICON[ci])
            how = how0 or (GEN_HOW[kind] % (cn, nid) if kind in GEN_HOW else "")
        if kind == "H": how = how or ON
        elif kind == "S": now, how = "+%A Strength", "SkyyGear applies it (1 Strength = +1% physical damage) through the gear:extras bridge - coming until the SkyyGear build that reads it is live"
        elif kind == "M": how = how or ON
        elif kind == "R": how = how or "SkyySkills applies it as a percent of the vanilla Mana refill (skill:fn:manaregen) - /skills mana lists it as trees"
        if role in (0, 1):
            if kind == "H": now = "+%A max Health"
            elif kind == "M": now = "+%A max Mana"
            elif kind == "R": now = "+%A% Mana Regen"
        if role == 7: how = "Waits for SkyyGear's elemental stats - the element of the " + pnames[lane - 1] + " path"
        elif role in (2, 3) and not how: how = "Comes with the class abilities: SkyyClasses lists Class.%s.%s when this class has them - until then it waits" % (cn, nid)
        if not hid: must_icon(icon)
        rk = CRANKS.get((cn, nid), [])
        sid = (_par[0] + "." + modid) if (role == 3 and not hid) else nid   # 0.3.13: the SAVED id (a modifier node: "<ability>.<Modifier>")
        CN.append(dict(ci=ci, n=ct_idx(nid), kind=kind, amt=amt, name=name, icon=icon, min=mn, now=now, how=how, hid=hid, rk=rk,
                       m2=CMANA2.get((cn, nid), 0), sid=sid, abid=abid, modid=modid))
assert len(CN) == NC * NN and all(c["ci"] * NN + c["n"] == k for k, c in enumerate(CN)), "CN is class-major"
for c in CN:   # 0.3.12: the icon hook (a hidden switch keeps its unused icon); 0.3.13: keyed by the saved id (Mage.A1.Power)
    if not c["hid"]: c["icon"] = node_icon("%s.%s" % (CLASSES[c["ci"]], c["sid"]), c["icon"])
_ART_KEYS |= set("%s.%s" % (CLASSES[c["ci"]], c["sid"]) for c in CN if not c["hid"])
assert set(NODE_ICON_ART) <= _ART_KEYS, "NODE_ICON_ART names a node that does not exist: %s" % sorted(set(NODE_ICON_ART) - _ART_KEYS)
assert all(len(c["name"]) <= 24 and "," not in c["name"] and "_" not in c["name"] and "~" not in c["name"] for c in CN)
# 0.3.13: per class the saved ids are unique (ignoring case), no saved id contains a separator of the saved line / the bridge csv
for _ci in range(NC):
    _sids = [c["sid"] for c in CN if c["ci"] == _ci and not c["hid"]]
    assert len(set(x.lower() for x in _sids)) == len(_sids) and all(re.fullmatch(r"[A-Z][A-Za-z0-9]*(\.[A-Z][A-Za-z]*)?", x) for x in _sids), _sids
assert all("~" not in c[f] for c in CN for f in ("now", "how", "icon", "sid", "abid", "modid"))
# every stat kind SkyyTrees applies shows its live amount (exactly one %A); no text holds a baked %d
assert all(c["now"].count("%A") == 1 for c in CN if c["kind"] in "HSMRVBCF" and c["kind"] != "-"), [c["name"] for c in CN if c["kind"] in "HSMRVBCF" and c["now"].count("%A") != 1]
assert all(c["now"].count("%A") <= 1 and "%d" not in c["now"] for c in CN)
assert [c["name"] for c in CN if CT_ID[c["n"]] == "X1"] == ["Edge", "Edge", "Wellspring", "Edge", "Wellspring", "Edge", "Edge", "Edge"]   # 0.3.10: + Spellblade
# the NOW nodes of the map (SkyyTrees alone): Warrior T2; Archer T4; Mage T1 T5; Priest T2 T5; Berserker T1; Monk T1 T2; Assassin T1 T4 (+ TS)
_now = sorted((CLASSES[c["ci"]], CT_ID[c["n"]]) for c in CN if CT[c["n"]][10] in (5, 6, 7, 9) and c["kind"] in "HMRVBCF" and c["kind"] != "-")   # 0.3.18: by role (pages moved)
assert _now == sorted([("Warrior", "T2"), ("Archer", "T4"), ("Mage", "T1"), ("Mage", "T5"), ("Priest", "T2"), ("Priest", "T5"), ("Berserker", "T1"),
                       ("Monk", "T1"), ("Monk", "T2"), ("Assassin", "T1"), ("Assassin", "T4")]), _now
# the 13 SkyyArmory-backed nodes of the map + the WAIT-MOVE ones (kind A as well; SkyyArmory lists them only when the move exists)
ARM13 = ["Mage.T2", "Mage.T3", "Mage.PA1", "Mage.PA2", "Mage.PA5", "Mage.PB1", "Priest.T1", "Monk.PB1", "Assassin.T3", "Assassin.PC1",
         "Assassin.PC2", "Assassin.PC3", "Assassin.PC4"]
assert all(CN[CLASSES.index(k.split(".")[0]) * NN + ct_idx(k.split(".")[1])]["kind"] == "A" for k in ARM13)
assert [c["name"] for c in CN if c["hid"] and CT_ID[c["n"]] == "TS"] == ["Switch"] * 7 and CN[CLASSES.index("Priest") * NN + ct_idx("TS")]["kind"] == "T"
# 0.3.13: the hidden ability / modifier slots = the Assassin's A4b column + every 5th slot of a 4-modifier ability
_HIDM = sorted((CLASSES[c["ci"]], CT_ID[c["n"]]) for c in CN if c["hid"] and CT[c["n"]][10] in (2, 3))
assert _HIDM == [("Assassin", "A4b")], _HIDM   # 0.3.18: no modifier slots - the Assassin's missing A1-alt B is the only hidden ability node
assert all(c["min"] == 0 for c in CN if CT[c["n"]][10] in (0, 1, 2)) and all(c["min"] > 0 for c in CN if CT[c["n"]][10] in (5, 6, 7, 9) and not c["hid"])
# 0.3.18: rows follow the class level (the spine has no level; an ability's is SkyyClasses' abil.unlock.*, built-in 1 / 10 / 20 / 30)
_ABLV = {"A1": 1, "A2": 10, "A3": 20, "A4a": 30, "A4b": 30}
def _lvl_of(ci_, n_):
    nid_ = CT_ID[n_]
    if nid_ in _ABLV: return _ABLV[nid_]
    return CN[ci_ * NN + n_]["min"]
for _ci in range(NC):
    for _pg in range(2):
        _rows = {}
        for _n in range(NN):
            if CT[_n][7] != _pg or CN[_ci * NN + _n]["hid"] or CT[_n][10] in (0, 1): continue
            _rows.setdefault(CT[_n][8], []).append(_lvl_of(_ci, _n))
        _keys = sorted(_rows)
        for _a, _b in zip(_keys, _keys[1:]):
            assert min(_rows[_b]) >= min(_rows[_a]), "0.3.18: %s page %d row %d opens below row %d's level: %s" % (CLASSES[_ci], _pg + 1, _b, _a, _rows)
        assert (max(max(v) for v in _rows.values()) <= 20) if _pg == 0 else (min(min(v) for v in _rows.values()) >= 20), (CLASSES[_ci], _pg, _rows)
assert [CT[ct_idx(a)][7:9] for a in ABL] == [(0, 1), (0, 3), (1, 0), (1, 2), (1, 2)] and CT[ct_idx("A2")][8] == CT[ct_idx("T2")][8] - 1
def _ctot(cn, kind, pick="X1"):
    ci = CLASSES.index(cn)
    return sum(c["amt"] for c in CN if c["ci"] == ci and c["kind"] == kind and CT_ID[c["n"]] != ("X2" if pick == "X1" else "X1") and CT[c["n"]][10] in (0, 1))
# page 1 + P4 keep 0.3.2's numbers (spine only now: the lanes are gone)
assert (_ctot("Warrior", "S"), _ctot("Warrior", "H"), _ctot("Warrior", "R")) == (7, 8, 5) == (_ctot("Monk", "S"), _ctot("Monk", "H"), _ctot("Monk", "R"))
assert (_ctot("Mage", "M"), _ctot("Mage", "R"), _ctot("Mage", "H")) == (13, 10, 8) == (_ctot("Priest", "M"), _ctot("Priest", "R"), _ctot("Priest", "H"))
# links (0.3.18): a bar is drawn from CT_DRAW's node, else from each same-page parent (T3 -> T4 crosses the page break without a bar; A3
# opens page 2). THE GOLD RULE (fix round, critic: "drawn lines promise a gate the buy rule doesn't enforce"): a bar lights only when BOTH
# nodes it joins are owned - a lit line is always two owned neighbours, never a bar through an unowned ability (T1 -> A2 -> T2 lights only
# with A2; a path bar under A3 only with A3). The buy rule (the real parents, "Needs") is 0.3.17's and unchanged.
def _drawn(k, n):
    if n[0] in CT_DRAW: return [CT_DRAW[n[0]]]
    return [p for p in n[2] if CT[ct_idx(p)][7] == n[7]]
CT_LINKS = [(ct_idx(p), k) for k, n in enumerate(CT) for p in _drawn(k, n)]
assert len(CT_LINKS) == NN - 2 + 1, len(CT_LINKS)   # every node but ROOT and A3 has one bar, P3 has two
LINK_LP = [a for (a, b) in CT_LINKS]
LINK_LD = [[b] for (a, b) in CT_LINKS]
def _lk(a, b): return CT_LINKS.index((ct_idx(a), ct_idx(b)))
assert (LINK_LP[_lk("ROOT", "A1")], LINK_LD[_lk("ROOT", "A1")]) == (0, [ct_idx("A1")])
assert (LINK_LP[_lk("T1", "A2")], LINK_LD[_lk("T1", "A2")]) == (ct_idx("T1"), [ct_idx("A2")])
assert (LINK_LP[_lk("A2", "T2")], LINK_LD[_lk("A2", "T2")]) == (ct_idx("A2"), [ct_idx("T2")])
assert (LINK_LP[_lk("A3", "PA1")], LINK_LD[_lk("A3", "PA1")]) == (ct_idx("A3"), [ct_idx("PA1")])
assert (LINK_LP[_lk("A3", "T4")], LINK_LD[_lk("A3", "T4")]) == (ct_idx("A3"), [ct_idx("T4")])
assert (LINK_LP[_lk("T4", "A4b")], LINK_LD[_lk("T4", "A4b")]) == (ct_idx("T4"), [ct_idx("A4b")])
assert (LINK_LP[_lk("X2", "P3")], LINK_LD[_lk("X2", "P3")]) == (ct_idx("X2"), [ct_idx("P3")])
CT_CELL = dict(((n[7], n[8], n[9]), k) for k, n in enumerate(CT))
# the bent links go through junction cells (a corner with no node); every other link is a straight bar
CT_BENT = {("A1", "P1"): [(1, 2)], ("A1", "TS"): [(1, 6)],                       # page 1: A1's fork to the spine (left) and the switch (right)
           ("P2", "X1"): [(3, 1)], ("P2", "X2"): [(3, 3)],                       # the spine's pick-one bracket opens under P2
           ("X1", "P3"): [(5, 1)], ("X2", "P3"): [(5, 3)],                       # ... and closes at P3
           ("A3", "PA1"): [(0, 0)], ("A3", "PB1"): [(0, 2)], ("A3", "PC1"): [(0, 6)],   # page 2: A3's fork to the three paths
           ("T4", "A4a"): [(1, 3)], ("T4", "A4b"): [(1, 5)]}                     # the A4 pick-one pair under T4
# 0.3.12 THE DOWNWARD RULE: a link's child sits on a LOWER row than its parent, and its way never climbs (a fork runs along the parent's row
# at most, then straight down)
for (_a, _b) in CT_LINKS:
    _way = [(CT[_a][8], CT[_a][9])] + CT_BENT.get((CT_ID[_a], CT_ID[_b]), []) + [(CT[_b][8], CT[_b][9])]
    assert CT[_b][8] > CT[_a][8], "0.3.12: %s -> %s does not go down" % (CT_ID[_a], CT_ID[_b])
    assert all(_way[_w + 1][0] >= _way[_w][0] for _w in range(len(_way) - 1)), "0.3.12: %s -> %s climbs: %s" % (CT_ID[_a], CT_ID[_b], _way)
# a slot's pieces (role): 0 the single bar of a straight pass-through cell, 1 up arm, 2 left arm, 3 centre, 4 right arm, 5 down arm,
# 6 the stub in the slot's right 4 px gap, 7 the stub in its bottom 4 px gap. PIECES[(page, row, col, role)] = [link indices]
PIECES, JUNCTION, HPASS = {}, set(), set()   # HPASS = the horizontal pass-through cells
def _piece(pg, r, c, role, li):
    PIECES.setdefault((pg, r, c, role), [])
    if li not in PIECES[(pg, r, c, role)]: PIECES[(pg, r, c, role)].append(li)
for (a, b) in CT_LINKS:   # 0.3.3: every bend first (a later link may pass through an earlier link's corner)
    for w in CT_BENT.get((CT_ID[a], CT_ID[b]), []): JUNCTION.add((CT[a][7],) + w)
for li, (a, b) in enumerate(CT_LINKS):
    pg = CT[a][7]
    way = [(CT[a][8], CT[a][9])] + CT_BENT.get((CT_ID[a], CT_ID[b]), []) + [(CT[b][8], CT[b][9])]
    for s_ in range(len(way) - 1):
        (r1, c1), (r2, c2) = way[s_], way[s_ + 1]
        assert r1 == r2 or c1 == c2, "a diagonal link: %s" % (way,)
        if r1 == r2:
            lo, hi = min(c1, c2), max(c1, c2)
            for c in range(lo, hi): _piece(pg, r1, c, 6, li)
            for c in range(lo + 1, hi):
                assert (pg, r1, c) not in CT_CELL, "a bar through a node cell"
                if (pg, r1, c) in JUNCTION: _piece(pg, r1, c, 2, li); _piece(pg, r1, c, 3, li); _piece(pg, r1, c, 4, li)
                else: _piece(pg, r1, c, 0, li); HPASS.add((pg, r1, c))
        else:
            lo, hi = min(r1, r2), max(r1, r2)
            for r in range(lo, hi): _piece(pg, r, c1, 7, li)
            for r in range(lo + 1, hi):
                assert (pg, r, c1) not in CT_CELL, "a bar through a node cell"
                if (pg, r, c1) in JUNCTION: _piece(pg, r, c1, 1, li); _piece(pg, r, c1, 3, li); _piece(pg, r, c1, 5, li)
                else: _piece(pg, r, c1, 0, li)
    for w in range(1, len(way) - 1):   # the corner's arms: towards the cell before and the cell after
        (r, c) = way[w]
        for (rr, cc) in (way[w - 1], way[w + 1]):
            role = 1 if rr < r else (5 if rr > r else (2 if cc < c else 4))
            _piece(pg, r, c, role, li)
        _piece(pg, r, c, 3, li)
assert all(not (pg, r, c) in CT_CELL for (pg, r, c) in JUNCTION) and len(JUNCTION) == 11
# 0.3.12: nothing overlaps - no pass-through cell carries a horizontal AND a vertical bar (a crossing would need a junction)
_VPASS = set()
for li, (a, b) in enumerate(CT_LINKS):
    _way = [(CT[a][8], CT[a][9])] + CT_BENT.get((CT_ID[a], CT_ID[b]), []) + [(CT[b][8], CT[b][9])]
    for _w in range(len(_way) - 1):
        (r1, c1), (r2, c2) = _way[_w], _way[_w + 1]
        if c1 == c2:
            for r in range(min(r1, r2) + 1, max(r1, r2)):
                if (CT[a][7], r, c1) not in JUNCTION: _VPASS.add((CT[a][7], r, c1))
assert not (_VPASS & HPASS), "0.3.12: a bar crosses another bar outside a junction: %s" % sorted(_VPASS & HPASS)
assert all(len(v) <= 3 for v in PIECES.values()), "a piece carries at most three links (the three paths share A3's corner)"
assert all(role not in (0,) or (pg, r, c) not in JUNCTION for (pg, r, c, role) in PIECES)
# slots: kind 0 empty, 1 node, 2 a horizontal pass-through bar, 3 a vertical one, 4 a junction; arms = 1 up, 2 left, 4 right, 8 down
NSLOT = 9 * CROWS   # 0.3.12: 63 (was 54: 6 rows)
SLOT_KIND, SLOT_NODE, SLOT_ARMS, SLOT_R, SLOT_D = [0] * (2 * NSLOT), [-1] * (2 * NSLOT), [0] * (2 * NSLOT), [False] * (2 * NSLOT), [False] * (2 * NSLOT)
for pg in range(2):
    for r in range(CROWS):
        for c in range(9):
            k = pg * NSLOT + r * 9 + c
            if (pg, r, c) in CT_CELL: SLOT_KIND[k], SLOT_NODE[k] = 1, CT_CELL[(pg, r, c)]
            elif (pg, r, c) in JUNCTION:
                SLOT_KIND[k] = 4
                for bit, role in ((1, 1), (2, 2), (4, 4), (8, 5)):
                    if (pg, r, c, role) in PIECES: SLOT_ARMS[k] |= bit
            elif (pg, r, c, 0) in PIECES: SLOT_KIND[k] = 2 if (pg, r, c) in HPASS else 3
            SLOT_R[k] = (pg, r, c, 6) in PIECES
            SLOT_D[k] = (pg, r, c, 7) in PIECES
assert SLOT_KIND.count(1) == NN and SLOT_KIND.count(4) == 11 and SLOT_KIND.count(2) == 5 and SLOT_KIND.count(3) == 1, (SLOT_KIND.count(2), SLOT_KIND.count(3))
# corners (right + down, left + down, up + right, up + left) and the fork tees (left + right + down) - no arm points up out of a fork
assert all(SLOT_ARMS[k] in (0, 4 | 8, 2 | 8, 1 | 4, 1 | 2, 2 | 4 | 8, 1 | 2 | 4) for k in range(2 * NSLOT)) and sum(1 for k in range(2 * NSLOT) if SLOT_ARMS[k]) == 11
assert [SLOT_KIND[9 + c] for c in range(9)] == [0, 0, 4, 2, 1, 2, 4, 0, 0] and [SLOT_ARMS[9 + c] for c in (2, 6)] == [4 | 8, 2 | 8]   # page 1 row 1: A1's fork
assert [SLOT_KIND[NSLOT + c] for c in range(9)] == [4, 2, 4, 2, 1, 2, 4, 0, 0] and [SLOT_ARMS[NSLOT + c] for c in (0, 2, 6)] == [4 | 8, 2 | 4 | 8, 2 | 8]   # page 2 row 0: A3's fork
assert [SLOT_KIND[NSLOT + 9 + c] for c in range(9)] == [1, 0, 1, 4, 1, 4, 1, 0, 0] and [SLOT_ARMS[NSLOT + 9 + c] for c in (3, 5)] == [4 | 8, 2 | 8]   # page 2 row 1: the A4 pair's fork
assert SLOT_KIND[NSLOT + 2 * 9 + 4] == 3, "T4 -> T5 passes between the A4 pair"
assert [SLOT_ARMS[r * 9 + c] for (r, c) in ((3, 1), (3, 3), (5, 1), (5, 3))] == [12, 10, 5, 3]
assert not any(SLOT_R[k] or SLOT_D[k] for k in range(2 * NSLOT) if SLOT_KIND[k] == 0), "a stub in an empty slot"
print("0.3.18 top-down class tree: page 1 %s | page 2 %s" % (" ".join("%s(%d,%d)" % (n[0], n[8], n[9]) for n in CT if n[7] == 0),
      " ".join("%s(%d,%d)" % (n[0], n[8], n[9]) for n in CT if n[7] == 1)))
PL1, PL2, PL3 = [-1] * (2 * NSLOT * 8), [-1] * (2 * NSLOT * 8), [-1] * (2 * NSLOT * 8)
for (pg, r, c, role), ls in PIECES.items():
    q = (pg * NSLOT + r * 9 + c) * 8 + role
    PL1[q] = ls[0]
    if len(ls) > 1: PL2[q] = ls[1]
    if len(ls) > 2: PL3[q] = ls[2]
assert sum(1 for x in PL1 if x >= 0) == len(PIECES) and sum(1 for x in PL3 if x >= 0) == 0   # 0.3.18: no piece carries a third link now
assert all(any(PL1[q] == li for q in range(len(PL1))) for li in range(len(CT_LINKS))), "every link is drawn"
# the cell state line (15 px bold, 96 px): every text the page can show fits
for _tx in ["Locked", "Owned", "Coming", "Pick one", "Turned off", "Respec", "Lv 100", "Lane 5", "Need 999 AP", "Unlock 9 AP", "Path locked",
            "All players", "Party only", "Kept", "Unlock free"] + ["Needs " + i for i in sorted(set(p for n in CT for p in n[2]))]:   # 0.3.13: the parents only
    assert SUI.text_width(_tx, 13, True) <= 86, (_tx, SUI.text_width(_tx, 13, True))   # 0.3.7: 13 px in the 86 px state line
assert SUI.text_width("Ability Points 50 of 50", 16, True) <= 190 and SUI.text_width("Swordsmanship 100", 18, True) <= 349
assert SUI.text_width("Assassination 100", 18, True) <= 349 and SUI.text_width("Respec 1,000,000,000 coins", 16, True) <= 230
assert SUI.text_width("Rune slots - coming with 0.7", 15, True, upper=True) <= 260 and all(SUI.text_width(cn, 17, True, upper=True) <= 172 - 48 for cn in CLASSES)
assert all(SUI.text_width(c["name"] + "  (" + c["sid"] + ")", 18, True) <= 344 for c in CN if not c["hid"])   # 0.3.13: the saved id
assert all(len(c["now"]) <= 90 and len(c["how"]) <= 170 for c in CN), [(c["name"], len(c["now"]), len(c["how"])) for c in CN if len(c["now"]) > 90 or len(c["how"]) > 170]

# ================= 0.3.25 tr_fit_check: every text of the detail well fits its box (beta bug 13: Zen panel text cut off) =================
# The detail well's boxes (the skill trees AND the class tab share them): name 14 px bold 1 line + state 16 px bold 2 lines beside the
# 68 px icon frame (344 px wide); Now / Next (Gives) 16 px 2 lines, Needs 16 px 3 lines, How 13 px 6 lines, Cost / Buy 16 px bold one
# line (424 px wide). Measured with the client's glyph tables (SUI.text_lines / text_width) on 95 % of the width.
TR_FIT_MARGIN = 0.95
TR_DET_TXT_W, TR_DET_NAME_W = 424, 424 - SUI.SLOT_FRAME - 12
TR_DET_NAME_H, TR_DET_STATE_H = 24, 44
TR_DET_LINE_H, TR_DET_NEED_H = 44, 66
TR_DET_HOW_H = int(6 * SUI.line_height(13)) + 1                          # 107: 6 lines of the 13 px summary text
assert TR_DET_NAME_H + TR_DET_STATE_H == SUI.SLOT_FRAME and TR_DET_HOW_H == 107


def _fit_cap(h, size, bold=False):
    return int(h // SUI.line_height(size, bold=bold))


def tr_fit_check():
    bad, n_ok = [], [0]

    def fit(what, tx, w, size, h, bold=False, wrap=True):
        ww = w * TR_FIT_MARGIN
        if wrap:
            got, cap = SUI.text_lines(tx, ww, size, bold), _fit_cap(h, size, bold)
        else:
            got, cap = SUI.text_width(tx, size, bold), ww
        if got > cap:
            bad.append("%s: %s (%s > %s): %s" % (what, "lines" if wrap else "px", round(got, 1), round(cap, 1), tx))
        else:
            n_ok[0] += 1

    W, NW = TR_DET_TXT_W, TR_DET_NAME_W
    # the texts every node can show (TreeClassOps / TreePage, fixed words)
    for tx in ["Chain broken - a needed node is missing or off, or its path is locked: no AP spent, no effect. A respec resets the tree",
               "Picking a path locks the other two (a respec frees them)", "Needs: a class (/class, or create a profile)",
               "Now: OFF - party members only (the default)", "Now: nothing - the chain is broken", "Now: turned off on this server (Faster tool swings is OFF)",
               "Your balance is negative (costs changed) - respec to get everything back", "Needs: your tree file to be fixed by an admin",
               "Needs: Your Ability Point balance is negative (the AP rules changed) - respec first, it is free right now"]:
        fit("fixed Needs / Now", tx, W, 16, TR_DET_NEED_H if tx.startswith(("Chain", "Needs", "Your", "Picking")) else TR_DET_LINE_H)
    for tx in ["Cost: free - kept from before", "Cost: 99 AP", "ON - every player - Switch for party only", "OFF - party only - Switch for every player",
               "Unlock - 99 AP", "Need 99 more AP", "Level 99 costs 999,999,999,999 Dust", "Unlock cost: 99 tokens", "Level up - 999.9B Dust"]:
        fit("Cost / Buy", tx, W, 16, 26, True, wrap=False)
    # ---- the class tab: every class x node
    STATES = ["Owned - switch ON", "Owned - switch OFF", "Owned - kept from before (free until a respec)", "Owned", "Owned - chain broken (see Needs)",
              "Unlockable", "Locked"]
    for c in CN:
        if c["hid"]:
            continue
        ci, cn = c["ci"], CLASSES[c["ci"]]
        lanes = CPATHS[cn][0]
        nid, _ap, par, need, lock, lane, _ln, pg, _r, _c, role = CT[c["n"]]
        byid = dict((CT_ID[x["n"]], x) for x in CN if x["ci"] == ci)
        tag = "%s.%s" % (cn, c["sid"])
        now = c["now"].replace("%A", "9999")
        typ = {1: "Passive - pick one of two", 2: "Ability", 3: "Modifier", 5: "Trunk", 9: "Switch"}.get(role, "Passive")   # = typeWord
        if role == 6: typ = (lanes[lane - 1] if lane else "Path") + " " + nid[2:] + "/5"
        if role == 7: typ = "Element - " + lanes[lane - 1] + " path"
        fit(tag + " name", c["name"] + "  (" + c["sid"] + ")", NW, 14, TR_DET_NAME_H, True)
        coming = ["Coming with SkyyGear's elemental stats (later)" if role == 7 else "Coming with runes (Hytale 0.7)", "Comes with the class abilities",
                  "Coming in a later build", "Coming with SkyyArmory"]
        for st in STATES + coming:
            fit(tag + " state", st + " - " + typ, NW, 16, TR_DET_STATE_H, True)
        fit(tag + " Now", "Now: ON - " + now, W, 16, TR_DET_LINE_H)
        fit(tag + " Gives", "Gives: " + now, W, 16, TR_DET_LINE_H)
        fit(tag + " How", c["how"], W, 13, TR_DET_HOW_H)
        nm = c["name"]
        needs = []
        if par:   # reasonText why 3: the gate parent(s), a skipped parent, a parent on the other page
            p0 = byid[par[0]]
            s = nm + " needs " + p0["name"] + " (" + p0["sid"] + ")"
            if len(par) > 1:
                s += " or " + byid[par[1]]["name"] + " (" + byid[par[1]]["sid"] + ")"
            s += " first"
            if CT[p0["n"]][10] not in (2, 3) and p0["kind"] in ("S", "X", "R", "A", "G", "L"):
                s += " (" + p0["sid"] + " waits for " + ("a later build" if p0["kind"] == "L" else "SkyyArmory") + " and is skipped)"
            if CT[p0["n"]][7] != pg:
                s += " - it is on page %d" % (CT[p0["n"]][7] + 1)
            needs.append(s)
        if need: needs.append(nm + " needs its ability " + byid[need]["name"] + " (" + byid[need]["sid"] + ") first")
        if lock: needs.append(nm + " cannot be taken together with " + byid[lock]["name"] + " - pick one of the two (a respec resets the choice)")
        if lane:
            other = max([x for x in lanes if x != lanes[lane - 1]], key=len)
            needs.append(nm + " is on the " + lanes[lane - 1] + " path - you follow " + other + " - respec to change paths")
            needs.append(nm + " needs 5 nodes of the " + lanes[lane - 1] + " path first (you own 4, 1 skipped)")
        needs += [nm + " needs " + CSKILL[ci] + " 100 (you are 99)", nm + " needs 99 AP - you have 98", nm + " is turned off on this server",
                  nm + " is coming with SkyyGear's elemental stats (later) - it cannot be unlocked yet",
                  nm + " comes with the class abilities - it cannot be unlocked yet"]
        for s in needs:
            fit(tag + " Needs", "Needs: " + s, W, 16, TR_DET_NEED_H)
        for w in ("SkyyGear's elemental stats (later)", "runes (Hytale 0.7)", "the class abilities", "SkyyArmory"):
            fit(tag + " Needs (waits)", "Waits for " + w + " - skipped until then: the nodes after it can be unlocked without it", W, 16, TR_DET_NEED_H)
    # ---- the skill trees: every node of every tree
    for r in ROWS:
        tn = TREES[r["t"]]
        tag = "%s.%s" % (tn, r["id"])
        who = " or ".join(r["readers"]) or "SkyySkills"
        nw = r["now"].replace("%V", "+999.9% (max)").replace("%C", "9999")
        fit(tag + " name", r["name"] + "  (S" + str(r["show"]) + ")", NW, 14, TR_DET_NAME_H, True)
        for st in ("Owned - level 99 / 99 - turned off", "Maxed - level 99 - turned off", "Coming with " + who, "Coming later"):
            fit(tag + " state", st, NW, 16, TR_DET_STATE_H, True)
        fit(tag + " Now", "Now: " + nw, W, 16, TR_DET_LINE_H)
        fit(tag + " Next", "Level 99: " + nw, W, 16, TR_DET_LINE_H)
        fit(tag + " How", r["how"].replace("%C", "9999").replace("%K", "Crouch + Ability 3"), W, 13, TR_DET_HOW_H)
        for s in ("Waits for the " + who + " build that applies it - your levels are kept, more wait until then",
                  "Needs: 99 tokens - you have 98 (1 more every 99 levels)", "Needs: 999,999,999 more Dust (1 per 99 " + tn + " XP)",
                  "Needs: " + tn + " 100 (you are 99)", "Needs: a Tier VI node first", "Draft - Skyy designs the rest of the " + tn + " tree later"):
            fit(tag + " Needs", s, W, 16, TR_DET_NEED_H)
        fit(tag + " Buy", "Coming with " + who, W, 16, 26, True, wrap=False)
    if bad:
        raise SystemExit("0.3.25 TEXT FIT: %d detail-well text(s) do not fit their box (beta bug 13) - shorten the text or grow the box:\n  %s"
                         % (len(bad), "\n  ".join(bad)))
    return n_ok[0]


TR_FIT_N = tr_fit_check()
print("0.3.25 text fit: %d detail-well texts of %d tree nodes and %d class nodes fit their boxes (%d %% of the width)"
      % (TR_FIT_N, len(ROWS), sum(1 for c in CN if not c["hid"]), round(TR_FIT_MARGIN * 100)))

# ================= default trees.properties =================
DL = ["# SkyyTrees %s - skill trees for Mining, Foraging, Farming, Cooking, Alchemy, Smithing, Acrobatics, Exploration and Fishing. /tree reload re-reads this file (perm skyytrees.admin)." % VERSION,
      "# Comments must stay on their own lines. A missing key uses the built-in default.",
      "# Also editable in game: SkyWynn Menu -> Server Setup -> Trees (SkyyMenu 0.3). Every change is logged in config-changes.log.",
      "# Skill level that opens tiers I..VI",
      "tier.levels=1,10,20,30,45,60",
      "# Tokens unlock nodes: level >= 1 -> first + floor(level / every)  (1 at level 1, 21 at level 100)",
      "tokens.first=1", "tokens.every=5",
      "# Dust levels nodes: floor(total skill XP / xpPerDust); node level n -> n+1 costs B x n^3 Dust",
      "dust.xpPerDust=10"] + ["# Per-tree Dust rate: dust.xpPerDust.<Tree> overrides dust.xpPerDust for that tree (a tree without a line uses dust.xpPerDust).",
      "# Acrobatics XP is capped per minute and Exploration XP is one-time, so their trees get more Dust per XP.",
      "# Mining and Smithing earn 1 Dust per 5 XP (Skyy 2026-10-02: Mining Dust doubled; Smithing XP comes slowly)."] + \
     ["dust.xpPerDust.%s=%d" % (t, DUST_DEF[t]) for t in TREES if t in DUST_DEF] + [
      "# Respec: free full refund of one tree; minutes between respecs of the same tree; optional coin price (SkyyCoins)",
      "respec.cooldownMinutes=10", "respec.coins=0",
      "# Abilities (Mining/Timber Spread, Vein Burst, Tree Feller) never run in these worlds (comma list of world names, e.g. the hub)",
      "ability.disabledWorlds=",
      "# Horizontal radius cap for Spread / Vein Burst / Tree Feller (and the vertical cap for Vein Burst)",
      "ability.maxRadius=6",
      "# Vein Burst + Tree Feller fire on EVERY qualifying break (0.3.24, Skyy 2026-10-18 \"a guarantee instead of a chance\"): cooldowns 0",
      "vein.cooldownSec=0",
      "# Tree Feller: breaks logs beside the cut on the SAME Y level only. Hytale itself fells the tree once its whole layer is cut.",
      "# LOCKED Skyy 2026-09-25 (research/Tree-Fall-Spec.md): feller.logs = extra logs at level 1, 2, 3 ... = 1, 2, 4, 5, 6, 10; levels 7-8",
      "# (the tree's 6 + your lifelong hatchet's Tree Feller, total up to 10) = 12, 14 since 0.3.21 (Skyy 2026-10-16, marker skyytrees-0.3.21-feller).",
      "# Level 6 jumps to 10 so a very large tree is not broken as a whole layer (that could crash). A level above the list uses its",
      "# last number. Cooldown 0 s since 0.3.24 (was 3; a hand-edited cooldown is kept).",
      "# feller.maxPerLayer = safety cap: one Tree Feller never breaks more logs than this, whatever feller.logs says.",
      "feller.logs=" + FELLER_LOGS_CSV,
      "feller.cooldownSec=0", "feller.maxPerLayer=64",
      "# Natural-tree check: the cut wood must touch leaves within feller.maxHeight blocks above or below the cut (nothing there is broken)",
      "feller.needLeaves=true", "feller.maxHeight=32",
      "# Felled trees (SkyySkills 0.4.2 pays every log that falls): those logs also roll Sap Tapper, Replanter and Pocket Change",
      "felled.nodes=true",
      "# Swing speed (0.2.3): Mining Speed / Chopping Speed shorten the wait between pickaxe / hatchet swings. Their per = fraction per",
      "# level (0.01 = 1%), whole percents, capped at +40% (then the swings are back to back). false = those two nodes do nothing.",
      "# 0.2.4: the hatchet (Chopping Speed) only swings faster when the swing chops wood - hits on mobs and other blocks keep vanilla speed.",
      "swing.enabled=true",
      "# Aggregated 'Tree bonus: ...' chat line at most every feedbackMs (per player; /tree quiet hides it)",
      "feedbackMs=2000",
      "# Testing only: extra tokens / Dust for every tree of every player",
      "debug.extraTokens=0", "debug.extraDust=0",
      "# ---- nodes: <Tree>.<Id>.max / per / B / tokens / enabled (Vein Burst + Double Jump also base; lists: items / crops) ----",
      "# per = amount per node level: a fraction for % nodes (0.02 = 2%), a flat amount for Health / Stamina, blocks for Vein Burst",
      "# (exactly base + per x level, every break), a fraction of your own jump height for Double Jump (base + per x level); Master Chef: per = chance",
      "# per level above 1. Tree Feller has no per / base (0.2.4): its logs per level are feller.logs above."]
def node_lines(r):
    tn = TREES[r["t"]]
    k = "%s.%s." % (tn, r["id"])
    out = ["# %s S%d %s (tier %s)" % (tn, r["show"], r["name"], ["I", "II", "III", "IV", "V", "VI"][r["tier"] - 1])]   # 0.3.17: reading order
    out.append(k + "max=%d" % r["max"])
    if KINDS[r["kind"]] != "FELLER": out.append(k + "per=%s" % repr(float(r["per"])))   # 0.2.4: Tree Feller reads feller.logs
    if KINDS[r["kind"]] in ("VEIN", "DJUMP"): out.append(k + "base=%s" % repr(float(r["base"])))
    out.append(k + "B=%d" % r["B"])
    out.append(k + "tokens=%d" % r["tok"])
    out.append(k + "enabled=true")
    if r["lk"]: out.append(k + r["lk"] + "=" + r["lst"])
    return out
SOON_NOTE = "# Exploration S5-S12 are 'Coming later' placeholders of the draft tree: they have no lines and can never be turned on"
for r in ROWS:
    if KINDS[r["kind"]] == "SOON" or r["t"] >= T03: continue   # 0.2 spec 4.1: no node lines for SOON slots; 0.3: the new trees follow
    DL.extend(node_lines(r))
DL.append(SOON_NOTE)
# 0.3: the Alchemy + Smithing lines, under a header carrying the update marker (TreeMig never touches a file whose comment lines hold it)
MG_MARK_ID = "skyytrees-0.3-trees"
DEF03_HEAD = ["# ---- Alchemy and Smithing trees (SkyyTrees 0.3; marker %s: the 0.3 update never runs on this file) ----" % MG_MARK_ID,
              "# Most of their nodes are applied by SkyySkills, SkyyGear or SkyySacks: such a node shows 'Coming with <mod>' and cannot be",
              "# bought until that mod says it applies it (bridge key tree:reads:<mod>). Deep Reserves and Forge Hardened work on their own."]
DL.extend(DEF03_HEAD)
for r in ROWS:
    if T03 <= r["t"] < T10: DL.extend(node_lines(r))
# 0.3.10: the Fishing tree's lines (a NEW server's file); an existing file is NOT rewritten - missing lines = these built-in numbers
DEF310_HEAD = ["# ---- Fishing tree (SkyyTrees 0.3.10; a file without these lines uses the same built-in numbers) ----",
               "# Every node but Sea Legs is applied by SkyyFishing or SkyySkills: it shows 'Coming with <mod>' until that mod says it applies it."]
DL.extend(DEF310_HEAD)
for r in ROWS:
    if r["t"] == T10: DL.extend(node_lines(r))
DL.extend(["# Farming tree level = the average of Farming, Ranching and Orchard (SkyySkills skill:farmavg) - false = the Farming level (0.3.10)",
           "farming.average=true"])
DL.extend(["# Replant (0.3.11): a felled natural tree gets its vanilla sapling on the stump, this many seconds after the last log (needs SkyySkills fell.nodes)",
           "trees.replant=true",
           "trees.replantDelaySec=5",
           "# Where the replant and the sapling drop work: all = everywhere (Skyy: for now), island = the player's own island only",
           "trees.replantWhere=all",
           "# Chance (percent, once per felled natural tree) to also get one matching sapling",
           "trees.saplingDropPct=10"])
DL.extend(["# Base Tree Sap (0.3.14): chance (percent, decimals allowed) per chopped natural log - hand, Tree Feller or felled - for +1 Tree Sap",
           "# (counts in SkyyCollections; stacks with Sap Tapper, whose sap from natural logs counts too since 0.3.21; never from placed logs)",
           "trees.sapBaseChance=10"])
MK317_ID = "skyytrees-0.3.17-foraging"   # 0.3.17: TreeMig317's run-once marker (a new default file carries it: nothing to move)
DL.extend(["# Foraging since SkyyTrees 0.3.17 (marker %s): Tree Feller is Tier III (1 token, B 100), Pocket Change Tier VI (3 tokens, B 7400, per 0.006)" % MK317_ID])
MK323_ID = "skyytrees-0.3.23-fortune"   # 0.3.23: TreeMig323's run-once marker (a new default file carries it: nothing to move)
DL.extend(["# Mining Fortune + Smelting Fortune since SkyyTrees 0.3.23 (marker " + MK323_ID + "): +10% a level (per 0.1), max 10 - 100% = one sure extra drop / bar, no total cap"])
