# 0.3 part 2: the class tree block - every class.* key TreeCfg reads has a line here (and in TreeMig's one-time block for an old file)
CLASS_SCALARS = [("class.enabled", "true"), ("class.ap.first", "1"), ("class.ap.every", "2"), ("class.ap.max", "50"),
                 ("class.respec.perLevel", "100"), ("class.undo", "true"), ("class.debug.extraAp", "0"),
                 ("class.ap.ability", "1"), ("class.ap.modifier", "1"), ("class.ap.spine", "0")]   # 0.3.13 (spec 4.1 + Q2)
CLASS_HEAD = ["# ---- Class trees (SkyyTrees 0.3 part 2: one Wynncraft-style tree per class, Ability Points from the class skill) ----",
              # 0.3.2: the marker of the one-time class trees ON update (TreeMig32 never touches a file whose comment lines hold it)
              "# class.enabled=true: class trees are ON by default since SkyyTrees 0.3.2 (Skyy 2026-10-05; marker %s)." % MK32_ID,
              # 0.3.3: the marker of the one-time class paths update (TreeMig33 never touches a file whose comment lines hold it)
              "# Page 2 = trunk T1-T6 + 3 locked paths PA / PB / PC since SkyyTrees 0.3.3 (2026-10-07; marker %s)." % MK33_ID,
              "# AP = first + floor(class skill level / every), capped at max (0 at level 0) + debug.extraAp. Spent AP = the owned nodes.",
              "# Class respec: coins = class skill level x perLevel (SkyyCoins); cooldown = respec.cooldownMinutes; undo = Undo on the page.",
              "# 0.3.13: ability nodes (A1 A2 A3 A4a A4b) cost class.ap.ability, modifier nodes (A1.Power ...) class.ap.modifier, the spine links",
              "# P1-P4 / X1 / X2 class.ap.spine (0 = free); the Root is free. A missing line = these defaults (1 / 1 / 0)."]
CLASS_LVL_HEAD = ["# Class skill level a node needs: class.minLevel.<Class>.<Id>=<level> (a deleted line or 0 = no level needed).",   # 0.3.1
                  "# 0.3.3: trunk T1-T6 at 5 / 10 / 15 / 25 / 40 / 55 (Archer T6 Holster Reload 75), path nodes 1-5 at 20 / 30 / 45 / 65 / 75,",
                  "# the elements LE / CE / RE at 75, the Priest switch TS at 1."]
CLASS_NODE_HEAD = ["# Nodes: class.nodes.<Class>.<Id>=<on>,<amount>,<AP>. amount = the node's number (Health / Strength / Mana points, a percent,",
                   "# blocks, bolts, seconds - what tree:fn:bonus answers); rune slots (A*, M*) and the elements (LE CE RE) come later, never buyable.",
                   "# Switching a node OFF refunds its AP (its chain breaks) and players may spend them, so switching it ON again can leave",
                   "# them over budget (effects stay, buying blocks, their respec is free): plan a respec round after such a change.",
                   "# Ids: ROOT P1 P2 X1 X2 P3 P4 (the spine; X1 / X2 = pick one; their AP = class.ap.spine), T1-T6 (trunk), PA1-PA5 PB1-PB5",
                   "# PC1-PC5 (the paths: the first one you own locks the other two), LE CE RE (elements), TS (Priest switch). The 0.3.2 lane lines",
                   "# (L1-L4 C1-C4 R1-R4 LS CS RS) are no longer read. 0.3.13: the ability + modifier nodes have no line (their AP rows are above);",
                   "# old class.nodes lines of A1-A4 / M1A-M4B are no longer read."]
def class_lines(ci):
    cn = CLASSES[ci]
    lanes = CLANES[cn]
    out = ["# %s (%s): paths %s (PA) / %s (PB) / %s (PC)" % (cn, CSKILL[ci], lanes[0][0], lanes[1][0], lanes[2][0])]
    for n in range(NN):
        c = CN[ci * NN + n]
        if c["hid"] or CT[n][10] in (2, 3): continue   # 0.3.3: no line for a hidden switch; 0.3.13: none for ability / modifier nodes
        out.append("class.nodes.%s.%s=true,%d,%d" % (cn, CT_ID[n], c["amt"], CT[n][1]))
    return out
CLASS_LINES = list(CLASS_HEAD) + ["%s=%s" % kv for kv in CLASS_SCALARS] + list(CLASS_LVL_HEAD) + \
              ["class.minLevel.%s.%s=%d" % (CLASSES[c["ci"]], CT_ID[c["n"]], c["min"]) for c in CN if c["min"] and not c["hid"]] + list(CLASS_NODE_HEAD)
for _ci in range(NC): CLASS_LINES += class_lines(_ci)
NHID = sum(1 for c in CN if c["hid"])
NMIN = sum(1 for c in CN if c["min"] and not c["hid"])
NABM = sum(1 for c in CN if CT[c["n"]][10] in (2, 3) and not c["hid"])   # 0.3.13: the ability nodes (no class.nodes line; 0.3.18: no modifier nodes)
assert NHID == 7 + len(_HIDM) and NMIN == NC * 24 + 1, (NHID, NMIN)   # 0.3.10: + the Spellblade's hidden Switch; per class trunk 6 + paths 15 + elements 3; TS only on the Priest
assert sum(1 for l in CLASS_LINES if not l.startswith("#")) == len(CLASS_SCALARS) + NMIN + NC * NN - NHID - NABM and all(ord(ch) < 128 and len(l) <= 160 for l in CLASS_LINES for ch in l)
