def _v3_keep(line):
    s = line.strip()
    if s.startswith("#"):
        return s not in _V3_DROP_COMMENTS
    k = s.split("=", 1)[0]
    if k in _V3_DROP_EXACT or k.startswith(_V3_DROP_PRE) or k.endswith(".B") or k.endswith(".tokens"):
        return False
    return True


