assert sorted(V3_SKILL_ORDER) == sorted(TREES + V3_NEW_PAGES), "every 0.3 tree has its v3 tree"
NV3 = len(V3T)
V3_PAGE = [len(TREES)] * NC + [TREES.index(_n) if _n in TREES else len(TREES) + 1 + V3_NEW_PAGES.index(_n) for _n in V3_SKILL_ORDER]
V3_OLD = [-1] * NC + [TREES.index(_n) if _n in TREES else -1 for _n in V3_SKILL_ORDER]
V3_SKILLKEY = [""] * NC + V3_SKILL_ORDER   # skill:fn:level names (SkyySkills: "Combat" = the current class skill, unknown = 0)
V3_TAB_LABEL = dict((_n, _n) for _n in V3_SKILL_ORDER)
V3_TAB_LABEL["Beastmastery"] = "Beasts"   # 0.4.0: 12 sub-tabs fit 1552 px only with this one shorter (the tree title says Beastmastery)


def _first_item(*ids):
    for _i in ids:
        if _i in ITEM_IDS:
            return _i
    raise SystemExit("none of these items exist: %s" % (ids,))


V3_SKILL_ICON = {"Mining": must("Tool_Pickaxe_Iron"), "Foraging": must("Tool_Hatchet_Iron"), "Combat": must("Weapon_Sword_Iron"),
                 "Beastmastery": _first_item("Ingredient_Hide_Medium", "Ingredient_Hide_Light", "Food_Wildmeat_Raw", "Plant_Fruit_Apple"),
                 "Farming": _first_item("Tool_Hoe_Iron", "Plant_Crop_Wheat_Item"), "Fishing": must("Fish_Trout_Rainbow_Item"),
                 "Alchemy": must("Potion_Health"), "Smithing": _first_item("Tool_Hammer_Iron", "Ingredient_Bar_Iron"),
                 "Cooking": must("Food_Pie_Apple"), "Acrobatics": must("Ingredient_Feathers_Light"), "Exploration": _first_item("Tool_Map", "Deco_Scroll")}
V3_ICON = list(CICON) + [V3_SKILL_ICON[_n] for _n in V3_SKILL_ORDER]
V3_COL = list(CCOLOR) + [TCOLOR[TREES.index(_n)] if _n in TREES else {"Combat": UI_DATA_COLORS[-2], "Beastmastery": UI_DATA_COLORS[-1]}[_n] for _n in V3_SKILL_ORDER]
for _c in V3_COL:
    assert re.fullmatch(r"#[0-9a-f]{6}", _c), _c
assert all(_c in UI_DATA_COLORS for _c in V3_COL), "0.4.0: the tree colours are data colours"
_V3_OLDIDX = dict((TREES[_r["t"]] + "." + _r["id"], _k) for _k, _r in enumerate(ROWS))
V3_ABNAME = {}   # SkyyClasses ability id -> its name (the class rows' free abilities)
V3_BR, V3_RW, V3_UP, V3_TR = [], [], [], []
for _tv, _t in enumerate(V3T):
    _tb0, _tr0, _tu0 = len(V3_BR), len(V3_RW), len(V3_UP)
    for _bn, _b in enumerate(_t["branches"]):
        _br0 = len(V3_RW)
        for _r in _b["rows"]:
            _u0 = len(V3_UP)
            for _u in _r["ups"]:
                _h = _u["hook"]
                _hk, _ha, _hm, _ho, _hl = 0, "", "", -1, 0
                _fxs = []   # 0.4.1 R3a: the (code, per rank) pairs of an fx hook
                if _h and _h[0] == "fx":
                    _hk, _fxs = 3, [(str(_c), float(_v)) for _c, _v in _h[1]]
                if _h and _h[0] == "mod":
                    _hk, _ha, _hm = 1, _h[1], _h[2]
                if _h and _h[0] == "old":
                    _hk, _ho, _hl = 2, _V3_OLDIDX[_h[1]], int(_h[2])
                _ic = MOD_ICON[_hm] if _hk == 1 else (ROWS[_ho]["icon"] if _hk == 2 else V3_ICON[_tv])
                V3_UP.append(dict(tv=_tv, b=len(V3_BR), row=len(V3_RW), id=_u["id"], name=_u["name"], max=_u["max"], cost=_u["cost"],
                                  text=_u["text"], hk=_hk, ha=_ha, hm=_hm, ho=_ho, hl=_hl, icon=_ic, fx=_fxs, now=_u.get("now", ""),
                                  key="%s.%s.b%d.%s" % ("Class" if _t["kind"] == "class" else "Skill", _t["name"], _bn + 1, _u["id"])))
            _f = _r["free"]
            _fk, _fline, _fab, _fo, _fl = 0, "", "", -1, 0
            if _f and _f["hook"] and _f["hook"][0] == "abil":
                _fk, _fline, _fab = 1, _f["hook"][1], _f["hook"][2]
                V3_ABNAME[_fab] = _f["name"]
            if _f and _f["hook"] and _f["hook"][0] == "old":
                _fk, _fo, _fl = 2, _V3_OLDIDX[_f["hook"][1]], int(_f["hook"][2])
            _ffx = ""
            if _f and _f["hook"] and _f["hook"][0] == "fx":   # 0.4.1 R3a: a free PASSIVE ability (the Assassin's Shadow Clone)
                _fk, _ffx = 3, str(_f["hook"][1])
            _fic = "" if not _f else (ABIL_ICON[0] if _t["kind"] == "class" else (ROWS[_fo]["icon"] if _fk == 2 else V3_ICON[_tv]))
            V3_RW.append(dict(tv=_tv, b=len(V3_BR), num=_r["r"], gate=_r["gate"], cap=_r["cap"], u0=_u0, un=len(_r["ups"]),
                              fname=_f["name"] if _f else "", ftext=_f["text"] if _f else "", fk=_fk, fline=_fline, fab=_fab, fo=_fo, fl=_fl, fic=_fic, ffx=_ffx))
        V3_BR.append(dict(tv=_tv, n=_bn + 1, name=_b["name"], theme=_b["theme"], r0=_br0, rn=len(_b["rows"])))
    V3_TR.append(dict(b0=_tb0, bn=len(V3_BR) - _tb0, r0=_tr0, rn=len(V3_RW) - _tr0, u0=_tu0, un=len(V3_UP) - _tu0))
NU3, NR3, NB3 = len(V3_UP), len(V3_RW), len(V3_BR)
for _x in V3_UP:
    must_icon(_x["icon"])
for _x in V3_RW:
    if _x["fic"]:
        must_icon(_x["fic"])
assert len(set(_u["key"] for _u in V3_UP)) == NU3, "a saved key twice"
assert all(V3_UP[_k]["row"] == _rw for _rw, _r in enumerate(V3_RW) for _k in range(_r["u0"], _r["u0"] + _r["un"]))
assert all("~" not in _u["text"] + _u["name"] and "\n" not in _u["text"] for _u in V3_UP)
for _u in V3_UP:   # every class modifier hook names an ability of ITS class that SkyyClasses knows and a modifier the page can name
    if _u["hk"] == 1:
        assert _u["ha"] in V3_ABNAME and _u["hm"] in C_MODNAME, _u
        assert _u["hm"] in [m for _ab in C_ABILS[CLASSES[_u["tv"]]] if _ab and _ab[0] == _u["ha"] for m in _ab[2]], ("not a modifier of that ability", _u)
_sum = {}
for _u in V3_UP:   # an old node's derived level never passes its built-in max (alias ranks + the free perks of open rows)
    if _u["hk"] == 2:
        _sum[_u["ho"]] = _sum.get(_u["ho"], 0) + _u["max"] * _u["hl"]
for _r in V3_RW:
    if _r["fk"] == 2:
        _sum[_r["fo"]] = _sum.get(_r["fo"], 0) + _r["fl"]
for _i, _v in _sum.items():
    assert _v <= ROWS[_i]["max"] or (ROWS[_i]["id"] == "MFortune" and _v <= 10), (TREES[ROWS[_i]["t"]], ROWS[_i]["id"], _v, ROWS[_i]["max"])
for _ci, _cn in enumerate(CLASSES):   # each ability line once per class tree; A1 = branch 1 row 1
    _ls = [_r["fline"] for _r in V3_RW if _r["tv"] == _ci and _r["fk"] == 1]
    assert len(_ls) == len(set(_ls)) and V3_RW[V3_TR[_ci]["r0"]]["fline"] == "A1", (_cn, _ls)
V3_LINES = ["A1", "A2", "A3", "A4a", "A4b"]
V3_DEAD = sorted(set(TREES[_r["t"]] + "." + _r["id"] for _k, _r in enumerate(ROWS) if KINDS[_r["kind"]] != "SOON")
                 - set(TREES[ROWS[_i]["t"]] + "." + ROWS[_i]["id"] for _i in _sum))
print("0.4.0 skill trees 3: %d trees, %d branches, %d rows, %d upgrades (%d hooked: %d class modifiers, %d old-node aliases), %d old nodes kept "
      "alive, %d old nodes without a v3 upgrade (R3): %s" % (NV3, NB3, NR3, NU3, sum(1 for _u in V3_UP if _u["hk"]),
      sum(1 for _u in V3_UP if _u["hk"] == 1), sum(1 for _u in V3_UP if _u["hk"] == 2), len(_sum), len(V3_DEAD), ", ".join(V3_DEAD)))
# fix round (critic HIGH): the row gates are FIXED at build time from this data table - min(5 x (r - 1), the ranks of the upgrades below
# that have a hook in this build) - so they never move while the server runs (a late reader mod, a node toggle) and an owned row ability is
# never taken away; Skyy's 0 / 5 / 10 / 15 / 20 / 25 wherever the rows below hold enough hooked ranks, lower only where R3 still has to wire
# upgrades (a dead row never locks the rows after it). R3: a gate that RISES (more hooks) must grandfather the row abilities it re-locks.
def _v3_hooked(_u):
    if _u["hk"] == 1 or _u["hk"] == 3:   # 0.4.1 R3a: every fx code is built (SkyyClasses 0.1.43 / SkyyArmory 0.1.41 / SkyyTrees)
        return True
    return _u["hk"] == 2 and KINDS[ROWS[_u["ho"]]["kind"]] != "SOON"


def _v3_hooked_old(_u):   # 0.4.1: the 0.4.0 rule (no fx hooks) = the gates players had until now (the one-time update compares)
    if _u["hk"] == 1:
        return True
    return _u["hk"] == 2 and KINDS[ROWS[_u["ho"]]["kind"]] != "SOON"


V3_GATES = []
for _tv in range(NV3):
    _cap = [0] * 8
    for _u in V3_UP:
        if _u["tv"] == _tv and _v3_hooked(_u):
            _cap[V3_RW[_u["row"]]["num"]] += _u["max"] * _u["cost"]
    _g, _below = [0] * 8, 0
    for _n in range(1, 8):
        _g[_n] = min(V3D.GATE_STEP * (_n - 1), _below)
        _below += _cap[_n]
    V3_GATES.extend(_g)
V3_ROWS_N = [max(_r["num"] for _r in V3_RW if _r["tv"] == _tv) for _tv in range(NV3)]
# 0.4.1: the 0.4.0 gates (the same rule without the fx hooks) - TreeV3.GATES_OLD; the one-time update grandfathers what they opened
V3_GATES_OLD = []
for _tv in range(NV3):
    _cap = [0] * 8
    for _u in V3_UP:
        if _u["tv"] == _tv and _v3_hooked_old(_u):
            _cap[V3_RW[_u["row"]]["num"]] += _u["max"] * _u["cost"]
    _g, _below = [0] * 8, 0
    for _n in range(1, 8):
        _g[_n] = min(V3D.GATE_STEP * (_n - 1), _below)
        _below += _cap[_n]
    V3_GATES_OLD.extend(_g)
assert all(V3_GATES[_tv * 8 + _n] == V3D.GATE_STEP * (_n - 1) for _tv in range(NC) for _n in range(1, 7)), "0.4.1: every class gate is Skyy's 0/5/10/15/20/25"
assert all(V3_GATES[_tv * 8 + _n] == V3_GATES_OLD[_tv * 8 + _n] for _tv in range(NC, NV3) for _n in range(8)), "0.4.1: the skill-tree gates do not move (R3b)"
assert all(V3_GATES[_i] >= V3_GATES_OLD[_i] for _i in range(len(V3_GATES))), "0.4.1: a gate only rises"
print("0.4.1 class gates raised from (0.4.0): " + "; ".join("%s %s" % (V3T[_tv]["name"], "/".join(str(V3_GATES_OLD[_tv * 8 + _n]) for _n in range(1, 7))) for _tv in range(NC)))
# 0.4.1 R3a: the fx entries flattened (one entry = one code of one upgrade), the owner of each code, the How words
V3_FX = []
for _k, _u in enumerate(V3_UP):
    _u["fx0"] = len(V3_FX)
    for _c, _v in _u["fx"]:
        V3_FX.append(dict(u=_k, code=_c, v=_v, own=V3D.fx_owner(_c)))
    _u["fxn"] = len(V3_FX) - _u["fx0"]
    assert (_u["hk"] == 3) == (_u["fxn"] > 0), _u["key"]
_FX_HOW = {"SkyyTrees": "SkyyTrees applies it to your stats.", "SkyyClasses": "SkyyClasses applies it in combat.", "SkyyArmory": "SkyyArmory applies it to your weapon."}
for _u in V3_UP:
    _os = sorted(set(V3_FX[_e]["own"] for _e in range(_u["fx0"], _u["fx0"] + _u["fxn"])))
    _u["fxhow"] = " ".join(_FX_HOW[_o] for _o in _os)
    _u["fxown"] = ",".join(V3_FX[_e]["own"] for _e in range(_u["fx0"], _u["fx0"] + _u["fxn"]))
assert all(_r["tv"] < NC for _r in V3_RW if _r["fk"] == 3) and all(_u["tv"] < NC for _u in V3_UP if _u["hk"] == 3), "fx = class trees only"
V3_FXCODES = sorted(set(_e["code"] for _e in V3_FX) | set(_r["ffx"] for _r in V3_RW if _r["fk"] == 3))
