F(cfg, "public static @LOG@ LOG;")
F(cfg, "public static final String DEFAULTS = " + json.dumps(DEFAULTS_V3) + ";")   # 0.4.0: a new server's file (no Token / Dust / AP lines)
F(cfg, "public static final String ADD02 = " + json.dumps(ADD02) + ";")
F(cfg, "public static final String ADD021DJ = " + json.dumps(ADD021DJ) + ";")
F(cfg, "public static final String ADD021FEL = " + json.dumps(ADD021FEL) + ";")
F(cfg, "public static final String ADD023 = " + json.dumps(ADD023) + ";")
F(cfg, "public static final String ADD024 = " + json.dumps(ADD024) + ";")
F(cfg, "public static final String ADD024DODGE = " + json.dumps(ADD024DODGE) + ";")
for decl in ("int[] TIER_LV = new int[] { 1, 10, 20, 30, 45, 60 }", "int TOK_FIRST = 1", "int TOK_EVERY = 5", "long XP_PER_DUST = 10L",
             "long RESPEC_CD_MS = 600000L", "long RESPEC_COINS = 0L", "String[] OFF_WORLDS = new String[0]", "int RADIUS = 6",
             "int FELLER_H = 32", "long VEIN_CD_MS = 0L", "long FELLER_CD_MS = 0L", "boolean FELLER_LEAVES = true",
             "int FELLER_ALL = 64", "int[] FELLER_LOGS = @FELLER_DEF@", "boolean FELLED_NODES = true", "boolean SWING_ON = true",
             "boolean FARM_AVG = true", "boolean HAS310 = true",   # 0.3.10: farming.average; the file holds Spellblade class lines
             "boolean REPLANT = true", "long REPLANT_MS = 5000L",   # 0.3.11: trees.replant, trees.replantDelaySec
             "boolean REPLANT_ISLAND = false", "int SAP_DROP_PCT = 10",   # 0.3.11: trees.replantWhere (island = true), trees.saplingDropPct
             "double SAP_BASE = 0.10",   # 0.3.14: trees.sapBaseChance (percent in the file, a fraction here)
             "long FEEDBACK_MS = 2000L", "long EXTRA_TOKENS = 0L", "long EXTRA_DUST = 0L",
             # 0.3 part 2: the class tree rows (class.*; the code defaults = the default file)
             "boolean CLASS_ON = true", "int AP_FIRST = 1", "int AP_EVERY = 2", "int AP_MAX = 50", "long C_RESPEC_PER = 100L",
             "boolean C_UNDO = true", "long C_EXTRA_AP = 0L",
             "int AP_ABIL = 1", "int AP_MOD = 1", "int AP_SPINE = 0",   # 0.3.13: class.ap.ability / class.ap.modifier / class.ap.spine
             "int AB_OFF = 0", "int M_IGN = 0",   # fix round (critic A3): ability nodes an admin switched off / old M1A-M4B lines saying false (logged when it changes)
             "boolean[] C_ON = " + jbool([True] * (NC * NN)), "int[] C_AMT = @PKG@.TreeClass.CAMT",
             "int[] C_AP = " + jint([CT[c["n"]][1] for c in CN]), "int[] C_MIN = @PKG@.TreeClass.CMIN", "boolean HAS33 = true",   # 0.3.13: 8 classes x 62 nodes (abilities + modifiers 1, the Root + spine 0)
             "long[] XP_T = " + jlong([DUST_DEF.get(t, 10) for t in TREES]),
             "int[] MAX = @PKG@.TreeDefs.D_MAX", "double[] PER = @PKG@.TreeDefs.D_PER", "long[] B = @PKG@.TreeDefs.D_B",
             "double[] BASE = @PKG@.TreeDefs.D_BASE", "int[] TOK = @PKG@.TreeDefs.D_TOK", "boolean[] EN = new boolean[] { " + ", ".join("false" if KINDS[r["kind"]] == "SOON" else "true" for r in ROWS) + " }",
             "Object[] LIST = new Object[%d]" % len(ROWS),
             # 0.4.0 Skill Trees 3: respec.perLevel / respec.maxSteps, the one-time Dust coin refund trees.dustCoinDivisor / trees.dustCoinCap
             "long V3_RBASE = 100L", "int V3_RSTEPS = 5", "long V3_DDIV = 1000L", "long V3_DCAP = 5000L"):
    F(cfg, "public static volatile %s;" % decl)
F(cfg, "public static volatile int AP_IGN = 0;")   # 0.3.7 second fix round: the last load's ignored A / M AP lines (logged when it changes)
M(cfg, r"""
public static void warn(String m) {
  try { if (LOG != null) LOG.at(java.util.logging.Level.WARNING).log("[SkyyTrees] " + m); } catch (Throwable t) { }
}""")
M(cfg, r"""
public static void info(String m) {
  try { if (LOG != null) LOG.at(java.util.logging.Level.INFO).log("[SkyyTrees] " + m); } catch (Throwable t) { }
}""")
M(cfg, r"""
public static String str(java.util.Properties p, String k, String d) {
  String v = p.getProperty(k);
  return v == null ? d : v.trim();
}""")
M(cfg, r"""
public static long lng(java.util.Properties p, String k, long d) {
  try { String v = p.getProperty(k); return v == null ? d : Long.parseLong(v.trim()); } catch (Throwable t) { return d; }
}""")
M(cfg, r"""
public static double dbl(java.util.Properties p, String k, double d) {
  try {
    String v = p.getProperty(k);
    if (v == null) return d;
    double x = Double.parseDouble(v.trim());
    return (Double.isNaN(x) || Double.isInfinite(x)) ? d : x;
  } catch (Throwable t) { return d; }
}""")
M(cfg, r"""
public static boolean bool(java.util.Properties p, String k, boolean d) {
  String v = p.getProperty(k);
  if (v == null) return d;
  v = v.trim();
  if (v.equalsIgnoreCase("true")) return true;
  if (v.equalsIgnoreCase("false")) return false;
  return d;
}""")
M(cfg, r"""
public static long clampL(long v, long lo, long hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}""")
M(cfg, r"""
public static double clampD(double v, double lo, double hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}""")
M(cfg, r"""
public static String[] split(String v) {
  java.util.ArrayList out = new java.util.ArrayList();
  if (v != null) {
    String[] xs = v.split(",");
    for (int i = 0; i < xs.length; i++) { String x = xs[i].trim(); if (x.length() > 0) out.add(x); }
  }
  String[] r = new String[out.size()];
  for (int i = 0; i < r.length; i++) r[i] = (String) out.get(i);
  return r;
}""")
M(cfg, r"""
public static int[] tiers(String v) {
  int[] def = new int[] { 1, 10, 20, 30, 45, 60 };
  String[] xs = split(v);
  if (xs.length != 6) { warn("tier.levels needs 6 numbers - using 1,10,20,30,45,60"); return def; }
  int[] r = new int[6];
  try {
    for (int i = 0; i < 6; i++) {
      r[i] = Integer.parseInt(xs[i]);
      if (r[i] < 0 || r[i] > 1000 || (i > 0 && r[i] < r[i - 1])) { warn("tier.levels must rise from 0 to 1000 - using 1,10,20,30,45,60"); return def; }
    }
  } catch (Throwable t) { warn("tier.levels is not 6 numbers - using 1,10,20,30,45,60"); return def; }
  return r;
}""")
# 0.2.4 feller.logs: extra logs at Tree Feller level 1, 2, 3 ... (1-20 whole numbers 1-256, each at least the one before; else the default)
M(cfg, r"""
public static int[] logs(String v) {
  int[] def = @FELLER_DEF@;
  String[] xs = split(v);
  if (xs.length < 1 || xs.length > 20) { warn("feller.logs needs 1 to 20 whole numbers - using @FELLER_CSV@"); return def; }
  int[] r = new int[xs.length];
  try {
    for (int i = 0; i < xs.length; i++) {
      r[i] = Integer.parseInt(xs[i]);
      if (r[i] < 1 || r[i] > 256 || (i > 0 && r[i] < r[i - 1])) { warn("feller.logs must be whole numbers 1-256, each at least the one before - using @FELLER_CSV@"); return def; }
    }
  } catch (Throwable t) { warn("feller.logs is not a list of whole numbers - using @FELLER_CSV@"); return def; }
  return r;
}""")
# extra logs at Tree Feller level lv: the table entry (a level above the table uses its last number), capped at feller.maxPerLayer
M(cfg, r"""
public static int fellerLogs(int lv) {
  if (lv <= 0) return 0;
  int[] t = FELLER_LOGS;
  if (t == null || t.length == 0) return 0;
  int n = t[(lv > t.length ? t.length : lv) - 1];
  int cap = FELLER_ALL;
  return n > cap ? cap : n;
}""")
M(cfg, r"""
public static long rate(int t) {
  long[] xt = XP_T;
  if (t >= 0 && t < xt.length && xt[t] > 0L) return xt[t];
  return XP_PER_DUST < 1L ? 1L : XP_PER_DUST;
}""")
M(cfg, r"""
public static boolean has02(java.util.Properties p) {
  java.util.Iterator it = p.stringPropertyNames().iterator();
  while (it.hasNext()) {
    String k = (String) it.next();
    if (k.startsWith("dust.xpPerDust.") || k.startsWith("Acrobatics.") || k.startsWith("Exploration.")) return true;
  }
  return false;
}""")
M(cfg, r"""
public static void apply(java.util.Properties p) {
  TIER_LV = tiers(str(p, "tier.levels", "1,10,20,30,45,60"));
  TOK_FIRST = (int) clampL(lng(p, "tokens.first", 1L), 0L, 100L);
  TOK_EVERY = (int) clampL(lng(p, "tokens.every", 5L), 1L, 100L);
  XP_PER_DUST = clampL(lng(p, "dust.xpPerDust", 10L), 1L, 1000000000L);
  long[] xt = new long[@PKG@.TreeDefs.NT];
  for (int tt = 0; tt < xt.length; tt++) {
    long dd = @PKG@.TreeDefs.D_DUST[tt] > 0L ? @PKG@.TreeDefs.D_DUST[tt] : XP_PER_DUST;
    xt[tt] = clampL(lng(p, "dust.xpPerDust." + @PKG@.TreeDefs.TREES[tt], dd), 1L, 1000000000L);
  }
  XP_T = xt;
  RESPEC_CD_MS = clampL(lng(p, "respec.cooldownMinutes", 10L), 0L, 100000L) * 60000L;
  RESPEC_COINS = clampL(lng(p, "respec.coins", 0L), 0L, 1000000000000L);
  OFF_WORLDS = split(str(p, "ability.disabledWorlds", ""));
  RADIUS = (int) clampL(lng(p, "ability.maxRadius", 6L), 1L, 16L);
  FELLER_H = (int) clampL(lng(p, "feller.maxHeight", 32L), 1L, 64L);
  VEIN_CD_MS = clampL(lng(p, "vein.cooldownSec", 0L), 0L, 86400L) * 1000L;      // 0.3.24: 0 = every qualifying break (was 40)
  FELLER_CD_MS = clampL(lng(p, "feller.cooldownSec", 0L), 0L, 86400L) * 1000L;   // 0.3.24: 0 = every log cut (was 3)
  FELLER_LEAVES = bool(p, "feller.needLeaves", true);
  FELLER_ALL = (int) clampL(lng(p, "feller.maxPerLayer", 64L), 1L, 256L);
  FELLER_LOGS = logs(str(p, "feller.logs", "@FELLER_CSV@"));
  FELLED_NODES = bool(p, "felled.nodes", true);
  SWING_ON = bool(p, "swing.enabled", true);
  FARM_AVG = bool(p, "farming.average", true);   // 0.3.10: the Farming tree's level = skill:farmavg (the three farming skills' average)
  REPLANT = bool(p, "trees.replant", true);                                          // 0.3.11
  REPLANT_MS = clampL(lng(p, "trees.replantDelaySec", 5L), 1L, 60L) * 1000L;
  REPLANT_ISLAND = str(p, "trees.replantWhere", "all").equalsIgnoreCase("island");   // all (default) / island
  SAP_DROP_PCT = (int) clampL(lng(p, "trees.saplingDropPct", 10L), 0L, 100L);
  SAP_BASE = Math.max(0.0, Math.min(100.0, dbl(p, "trees.sapBaseChance", 10.0))) / 100.0;   // 0.3.14
  FEEDBACK_MS = clampL(lng(p, "feedbackMs", 2000L), 500L, 600000L);
  EXTRA_TOKENS = clampL(lng(p, "debug.extraTokens", 0L), 0L, 1000L);
  EXTRA_DUST = clampL(lng(p, "debug.extraDust", 0L), 0L, 1000000000000000L);
  V3_RBASE = clampL(lng(p, "respec.perLevel", 100L), 0L, 1000000000L);                    // 0.4.0: respec = this x level x min(n, steps)
  V3_RSTEPS = (int) clampL(lng(p, "respec.maxSteps", 5L), 1L, 100L);
  V3_DDIV = clampL(lng(p, "trees.dustCoinDivisor", 100L), 1L, 1000000000000L);            // 0.4.0: 1 refund coin per this much Dust
  V3_DCAP = clampL(lng(p, "trees.dustCoinCap", 25000L), 0L, 1000000000000L);                // 0.4.0: refund coins per tree at most
  int n = @PKG@.TreeDefs.N;
  int[] mx = new int[n];
  double[] pe = new double[n];
  long[] bb = new long[n];
  double[] ba = new double[n];
  int[] tk = new int[n];
  boolean[] en = new boolean[n];
  Object[] li = new Object[n];
  for (int i = 0; i < n; i++) {
    String k = @PKG@.TreeDefs.TREES[i / 12] + "." + @PKG@.TreeDefs.ID[i] + ".";
    mx[i] = (int) clampL(lng(p, k + "max", (long) @PKG@.TreeDefs.D_MAX[i]), 1L, 100L);
    pe[i] = clampD(dbl(p, k + "per", @PKG@.TreeDefs.D_PER[i]), 0.0, 1000.0);
    bb[i] = clampL(lng(p, k + "B", @PKG@.TreeDefs.D_B[i]), 0L, 1000000000L);
    ba[i] = clampD(dbl(p, k + "base", @PKG@.TreeDefs.D_BASE[i]), 0.0, 1000.0);
    tk[i] = (int) clampL(lng(p, k + "tokens", (long) @PKG@.TreeDefs.D_TOK[i]), 0L, 100L);
    en[i] = !@PKG@.TreeDefs.soon(i) && bool(p, k + "enabled", true);
    String lk = @PKG@.TreeDefs.LISTKEY[i];
    if (lk.length() > 0) li[i] = split(str(p, k + lk, @PKG@.TreeDefs.D_LIST[i]));
  }
  MAX = mx; PER = pe; B = bb; BASE = ba; TOK = tk; EN = en; LIST = li;
  // 0.3 part 2: the class tree (class.nodes.<Class>.<Id>=<on>,<amount>,<ap>; class.minLevel.<Class>.<Id>); 0.3.2: class.enabled
  // defaults to ON (Skyy 2026-10-05) - a missing or unreadable line reads true
  CLASS_ON = bool(p, "class.enabled", true);
  AP_FIRST = (int) clampL(lng(p, "class.ap.first", 1L), 0L, 10L);
  AP_EVERY = (int) clampL(lng(p, "class.ap.every", 2L), 1L, 20L);
  AP_MAX = (int) clampL(lng(p, "class.ap.max", 50L), 1L, 200L);
  C_RESPEC_PER = clampL(lng(p, "class.respec.perLevel", 100L), 0L, 1000000000L);
  C_UNDO = bool(p, "class.undo", true);
  C_EXTRA_AP = clampL(lng(p, "class.debug.extraAp", 0L), 0L, 1000L);
  int apAb = (int) clampL(lng(p, "class.ap.ability", 1L), 0L, 10L);    // 0.3.13 (spec 4.1): an ability node
  int apMd = (int) clampL(lng(p, "class.ap.modifier", 1L), 0L, 10L);   // 0.3.13: a modifier node
  int apSp = (int) clampL(lng(p, "class.ap.spine", 0L), 0L, 10L);      // 0.3.13 (spec Q2: free links): P1-P4, X1, X2
  AP_ABIL = apAb; AP_MOD = apMd; AP_SPINE = apSp;
  int cnn = @PKG@.TreeClass.NC * @PKG@.TreeClass.NN;
  int abOff = 0;      // fix round (critic A3): ability nodes switched off by a class.nodes line (A1 A2 A3 A4a A4b, or the 0.3.12 A4 line = both alts)
  String abOffAt = "";
  int mIgn = 0;       // ... and old M1A-M4B lines that say false (the modifier slots come with the ability now - not read)
  String mIgnAt = "";
  int apIgn = 0;   // 0.3.7 second fix round: non-0 AP lines of A / M nodes (ignored)
  String apIgnAt = "";
  boolean[] con = new boolean[cnn];
  int[] cam = new int[cnn];
  int[] cap = new int[cnn];
  int[] cmn = new int[cnn];
  for (int j = 0; j < cnn; j++) {
    int ci = j / @PKG@.TreeClass.NN;
    int nn = j % @PKG@.TreeClass.NN;
    con[j] = true;
    cam[j] = @PKG@.TreeClass.CAMT[j];
    cap[j] = @PKG@.TreeClass.NAP[nn];
    String ck = "class.nodes." + @PKG@.TreeClass.CLASSES[ci] + "." + @PKG@.TreeClass.NID[nn];
    String cv = p.getProperty(ck);
    if (cv != null) {
      String[] xs = cv.split(",", -1);
      if (xs.length >= 1 && xs[0].trim().equalsIgnoreCase("false")) con[j] = false;
      if (xs.length >= 2) { try { cam[j] = (int) clampL(Long.parseLong(xs[1].trim()), 0L, 1000L); } catch (Throwable t1) { } }
      if (xs.length >= 3) { try { cap[j] = (int) clampL(Long.parseLong(xs[2].trim()), 0L, 10L); } catch (Throwable t2) { } }
    }
    int rl = @PKG@.TreeClass.NROLE[nn];   // 0.3.13: the ability + modifier nodes cost the AP rows (a line's amount / AP is not read)
    if (rl == 2) {   // fix round (critic A3): an ability node keeps an admin's OFF switch (its own line, or the 0.3.12 A4 line for A4a / A4b)
      boolean off = !con[j];
      if (!off && @PKG@.TreeClass.NID[nn].startsWith("A4")) {
        String ov = p.getProperty("class.nodes." + @PKG@.TreeClass.CLASSES[ci] + ".A4");
        if (ov != null && ov.split(",", -1)[0].trim().equalsIgnoreCase("false")) off = true;
      }
      con[j] = !off; cam[j] = 0; cap[j] = apAb;
      if (off && !@PKG@.TreeClass.hidden(ci, nn)) { abOff++; if (abOffAt.length() == 0) abOffAt = "class.nodes." + @PKG@.TreeClass.CLASSES[ci] + "." + @PKG@.TreeClass.NID[nn]; }
    }
    else if (rl == 3) { con[j] = true; cam[j] = 0; cap[j] = apMd; }
    else if (rl == 0 || rl == 1) {
      if (nn != 0 && cv != null && cv.split(",", -1).length >= 3 && cap[j] != apSp && cap[j] != 1) { apIgn++; if (apIgnAt.length() == 0) apIgnAt = ck; }   // an admin's own spine price
      cap[j] = nn == 0 ? 0 : apSp;   // the Root is free; the spine costs class.ap.spine
    }
    // 0.3.1 (Skyy 2026-10-03): a DELETED class.minLevel line = no class level needed (0.3 kept the built-in 15 / 15 / 50); 0 = none as
    // before; a line that is there but holds no number keeps the built-in level (a typo cannot drop the lock)
    String mk = "class.minLevel." + @PKG@.TreeClass.CLASSES[ci] + "." + @PKG@.TreeClass.NID[nn];
    cmn[j] = p.getProperty(mk) == null ? 0 : (int) clampL(lng(p, mk, (long) @PKG@.TreeClass.CMIN[j]), 0L, 100L);
  }
  if (apIgn > 0 && apIgn != AP_IGN) info(apIgn + " class.nodes line(s) set their own AP cost on a spine node (first: " + apIgnAt + ") - since 0.3.13 the spine costs class.ap.spine (Server Setup -> Trees -> Class trees); the line's AP is not read.");
  for (int cq = 0; cq < @PKG@.TreeClass.NC; cq++) {   // fix round (critic A3): the old modifier SLOT lines are not read any more
    for (int lq = 1; lq <= 4; lq++) {
      for (int aq = 0; aq < 2; aq++) {
        String mk0 = "class.nodes." + @PKG@.TreeClass.CLASSES[cq] + ".M" + lq + (aq == 0 ? "A" : "B");
        String mv = p.getProperty(mk0);
        if (mv != null && mv.split(",", -1)[0].trim().equalsIgnoreCase("false")) { mIgn++; if (mIgnAt.length() == 0) mIgnAt = mk0; }
      }
    }
  }
  if (abOff > 0 && abOff != AB_OFF) info(abOff + " ability node(s) are switched OFF by a class.nodes line (first: " + abOffAt + "; a 0.3.12 A4 line switches both A4a and A4b) - nobody can buy or use those abilities. Only the on / off of such a line is read (the AP is the AP per ability node row).");
  if (mIgn > 0 && mIgn != M_IGN) info(mIgn + " old modifier slot line(s) say false (first: " + mIgnAt + ") - since 0.3.13 an ability's 2 modifier slots come with its ability node, so M1A-M4B lines are not read. Switch the ability node off instead (class.nodes.<Class>.A1 ... A4a / A4b = false).");
  AB_OFF = abOff;
  M_IGN = mIgn;
  AP_IGN = apIgn;
  // 0.3.3 fix 2: no class.nodes line of a pair new in 0.3.3 = the 0.3.3 lines are not in this file (TreeMig33 refused / failed, or a
  // pre-0.3.3 History version was put back): a missing class.minLevel line of a NEW pair keeps its built-in level until they are appended
  boolean has33 = false;
  for (int j = 0; j < cnn && !has33; j++) {
    if (!@PKG@.TreeClass.NEW33[j]) continue;
    if (p.getProperty("class.nodes." + @PKG@.TreeClass.CLASSES[j / @PKG@.TreeClass.NN] + "." + @PKG@.TreeClass.NID[j % @PKG@.TreeClass.NN]) != null) has33 = true;
  }
  if (!has33) {
    for (int j = 0; j < cnn; j++) {
      if (!@PKG@.TreeClass.NEW33[j]) continue;
      String mk2 = "class.minLevel." + @PKG@.TreeClass.CLASSES[j / @PKG@.TreeClass.NN] + "." + @PKG@.TreeClass.NID[j % @PKG@.TreeClass.NN];
      if (p.getProperty(mk2) == null) cmn[j] = @PKG@.TreeClass.CMIN[j];
    }
  }
  HAS33 = has33;
  // 0.3.10: the same rule for the Spellblade (SkyyClasses 0.1.25): no class.nodes.Spellblade line = its lines are not in this file (no
  // migration writes them) - a missing class.minLevel line of a Spellblade node keeps its built-in level instead of "no level needed"
  boolean has310 = false;
  for (int j = 0; j < cnn && !has310; j++) {
    if (!@PKG@.TreeClass.NEW310[j]) continue;
    if (p.getProperty("class.nodes." + @PKG@.TreeClass.CLASSES[j / @PKG@.TreeClass.NN] + "." + @PKG@.TreeClass.NID[j % @PKG@.TreeClass.NN]) != null) has310 = true;
  }
  if (!has310) {
    for (int j = 0; j < cnn; j++) {
      if (!@PKG@.TreeClass.NEW310[j]) continue;
      String mk3 = "class.minLevel." + @PKG@.TreeClass.CLASSES[j / @PKG@.TreeClass.NN] + "." + @PKG@.TreeClass.NID[j % @PKG@.TreeClass.NN];
      if (p.getProperty(mk3) == null) cmn[j] = @PKG@.TreeClass.CMIN[j];
    }
  }
  HAS310 = has310;
  C_ON = con; C_AMT = cam; C_AP = cap; C_MIN = cmn;
}""")
M(cfg, r"""
public static void writeAtomic(byte[] data) throws java.io.IOException {
  java.nio.file.Path tmp = FILE.resolveSibling(FILE.getFileName().toString() + ".tmp");
  java.nio.file.Files.write(tmp, data, new java.nio.file.OpenOption[0]);
  java.io.IOException last = null;
  for (int i = 0; i < 5; i++) {
    try {
      java.nio.file.Files.move(tmp, FILE, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.ATOMIC_MOVE, java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      return;
    } catch (java.nio.file.AtomicMoveNotSupportedException e) {
      java.nio.file.Files.move(tmp, FILE, new java.nio.file.CopyOption[] { java.nio.file.StandardCopyOption.REPLACE_EXISTING });
      return;
    } catch (java.nio.file.FileSystemException e) {
      last = e;
    }
    try { Thread.sleep(20L); } catch (InterruptedException ie) { }
  }
  try { java.nio.file.Files.deleteIfExists(tmp); } catch (Throwable x) { }
  throw last;
}""")
M(cfg, r"""
public static boolean hasPrefix(java.util.Properties p, String pre) {
  java.util.Iterator it = p.stringPropertyNames().iterator();
  while (it.hasNext()) {
    String k = (String) it.next();
    if (k.startsWith(pre)) return true;
  }
  return false;
}""")
# one "key=value" line whose key AND value text equal (key, old) -> "key=neu" (its \r kept); anything else (comments, other keys,
# custom values, other separators) -> null = untouched
M(cfg, r"""
public static String migrateLine(String ln, String key, String old, String neu) {
  String body = ln;
  String cr = "";
  if (body.endsWith("\r")) { body = body.substring(0, body.length() - 1); cr = "\r"; }
  String tb = body.trim();
  if (tb.length() == 0 || tb.charAt(0) == '#' || tb.charAt(0) == '!') return null;
  int eq = body.indexOf('=');
  if (eq <= 0) return null;
  if (!body.substring(0, eq).trim().equals(key)) return null;
  if (!body.substring(eq + 1).trim().equals(old)) return null;
  return key + "=" + neu + cr;
}""")
# 0.2.1 Tree Feller rework: the unchanged 0.1 / 0.2 default lines only (n[0] = lines changed)
M(cfg, r"""
public static String migrateFeller(String text, int[] n) {
  String[] ls = text.split("\n", -1);
  StringBuilder sb = new StringBuilder(text.length() + 16);
  for (int i = 0; i < ls.length; i++) {
    String ln = ls[i];
    String r = migrateLine(ln, "Foraging.FFeller.per", "8.0", "1.0");
    if (r == null) r = migrateLine(ln, "Foraging.FFeller.base", "8.0", "0.0");
    if (r == null) r = migrateLine(ln, "feller.cooldownSec", "30", "3");
    if (r != null) { ln = r; n[0] = n[0] + 1; }
    if (i > 0) sb.append('\n');
    sb.append(ln);
  }
  return sb.toString();
}""")
# 0.2.3 swing speed: the untouched old default lines Mining.MSpeed.per=0.02 / Foraging.FSpeed.per=0.02 -> 0.01 (n[0] = lines changed);
# a custom value is kept (upgrade warns about it)
M(cfg, r"""
public static String migrateSwing(String text, int[] n) {
  String[] ls = text.split("\n", -1);
  StringBuilder sb = new StringBuilder(text.length() + 16);
  for (int i = 0; i < ls.length; i++) {
    String ln = ls[i];
    String r = migrateLine(ln, "Mining.MSpeed.per", "0.02", "0.01");
    if (r == null) r = migrateLine(ln, "Foraging.FSpeed.per", "0.02", "0.01");
    if (r != null) { ln = r; n[0] = n[0] + 1; }
    if (i > 0) sb.append('\n');
    sb.append(ln);
  }
  return sb.toString();
}""")
# 0.2.4: the untouched old default lines Foraging.FFeller.max=5 -> 6 (Tree Feller levels 1-6) and Acrobatics.RDouble.B=150 -> 500 (Double
# Jump's new tier III slot) (n[0] = lines changed); custom values are kept (upgrade warns about them)
M(cfg, r"""
public static String migrate024(String text, int[] n) {
  String[] ls = text.split("\n", -1);
  StringBuilder sb = new StringBuilder(text.length() + 16);
  for (int i = 0; i < ls.length; i++) {
    String ln = ls[i];
    String r = migrateLine(ln, "Foraging.FFeller.max", "5", "6");
    if (r == null) r = migrateLine(ln, "Acrobatics.RDouble.B", "150", "500");
    if (r != null) { ln = r; n[0] = n[0] + 1; }
    if (i > 0) sb.append('\n');
    sb.append(ln);
  }
  return sb.toString();
}""")
# ONE atomic write for everything an older trees.properties is missing: the 0.2 block (a 0.1 file; it already carries the Double Jump
# lines), the Double Jump block (a 0.2 file), the Tree Feller migration + block (any file without feller.maxPerLayer), the 0.2.3 swing
# migration + block (any file without swing.enabled - research/Swing-Speed-Spec.md 4.2), the 0.2.4 migration + block (any file without
# feller.logs; + the Quick Dodge lines when a 0.2.1-0.2.3 file has none). The returned
# settings are parsed from exactly the new content (ISO-8859-1 = what Properties.load(InputStream) reads), so a failed write still runs
# with the migrated numbers and the next load simply tries again.
M(cfg, r"""
public static java.util.Properties upgrade(java.util.Properties p) {
  boolean need02 = !has02(p);
  boolean needDj = !need02 && !hasPrefix(p, "Acrobatics.RDouble.");
  boolean needFel = p.getProperty("feller.maxPerLayer") == null;
  boolean need023 = p.getProperty("swing.enabled") == null;
  boolean need024 = p.getProperty("feller.logs") == null;
  boolean needDodge = need024 && !need02 && !hasPrefix(p, "Acrobatics.RDodge.");
  if (!need02 && !needDj && !needFel && !need023 && !need024) return p;
  java.util.Properties q = p;
  try {
    byte[] old = java.nio.file.Files.readAllBytes(FILE);
    String text = new String(old, "ISO-8859-1");
    int[] n = new int[1];
    if (needFel) text = migrateFeller(text, n);
    int[] n2 = new int[1];
    if (need023) text = migrateSwing(text, n2);
    int[] n3 = new int[1];
    if (need024) text = migrate024(text, n3);
    StringBuilder sb = new StringBuilder(text);
    if (need02) sb.append("\n").append(ADD02);
    if (needDj) sb.append("\n").append(ADD021DJ);
    if (needFel) sb.append("\n").append(ADD021FEL);
    if (need023) sb.append("\n").append(ADD023);
    if (need024) sb.append("\n").append(ADD024);
    if (needDodge) sb.append(ADD024DODGE);
    byte[] data = sb.toString().getBytes("ISO-8859-1");
    java.util.Properties np = new java.util.Properties();
    np.load(new java.io.ByteArrayInputStream(data));
    q = np;
    try {
      writeAtomic(data);
      info("updated " + FILE + " for SkyyTrees 0.2.4:" + (need02 ? " added the 0.2 lines (Acrobatics and Exploration trees, per-tree Dust rates);" : "") + (needDj ? " added the Double Jump lines;" : "") + (needFel ? " Tree Feller rework (" + n[0] + " old default line(s) changed, feller.maxPerLayer added);" : "") + (need023 ? " swing speed (" + n2[0] + " old default Mining Speed / Chopping Speed line(s) changed to per=0.01, swing.enabled added);" : "") + (need024 ? " Tree Feller table + Double Jump in tier III (" + n3[0] + " old default line(s) changed, feller.logs added" + (needDodge ? ", Quick Dodge lines added" : "") + ")" : ""));
    } catch (Throwable t2) { warn("could not update trees.properties (the new values apply anyway, the next load tries again): " + t2); }
  } catch (Throwable t) {
    warn("could not read trees.properties for the update (the old default values are migrated in memory only): " + t);
    q = new java.util.Properties();
    q.putAll(p);
    if (needFel) {
      if ("8.0".equals(str(q, "Foraging.FFeller.per", ""))) q.setProperty("Foraging.FFeller.per", "1.0");
      if ("8.0".equals(str(q, "Foraging.FFeller.base", ""))) q.setProperty("Foraging.FFeller.base", "0.0");
      if ("30".equals(str(q, "feller.cooldownSec", ""))) q.setProperty("feller.cooldownSec", "3");
    }
    if (need023) {
      if ("0.02".equals(str(q, "Mining.MSpeed.per", ""))) q.setProperty("Mining.MSpeed.per", "0.01");
      if ("0.02".equals(str(q, "Foraging.FSpeed.per", ""))) q.setProperty("Foraging.FSpeed.per", "0.01");
    }
    if (need024) {
      if ("5".equals(str(q, "Foraging.FFeller.max", ""))) q.setProperty("Foraging.FFeller.max", "6");
      if ("150".equals(str(q, "Acrobatics.RDouble.B", ""))) q.setProperty("Acrobatics.RDouble.B", "500");
    }
  }
  // 0.2.4: Foraging.FFeller.per / base are no longer read (feller.logs), so the 0.2.1 "custom Feller numbers kept" warning is gone
  if (need024) {
    String fm = q.getProperty("Foraging.FFeller.max");
    if (fm != null && !"6".equals(fm.trim())) warn("Foraging.FFeller.max=" + fm.trim() + " kept - Tree Feller levels follow feller.logs since 0.2.4 (1, 2, 4, 5, 6, 10 at levels 1-6; a level above the list uses its last number)");
    String db = q.getProperty("Acrobatics.RDouble.B");
    if (db != null && !"500".equals(db.trim())) warn("Acrobatics.RDouble.B=" + db.trim() + " kept - Double Jump is Acrobatics tier III (S7) since 0.2.4, where the template price is 500");
    if (q.getProperty("Foraging.FFeller.per") != null || q.getProperty("Foraging.FFeller.base") != null) info("Foraging.FFeller.per / base are no longer read (Tree Feller uses feller.logs since 0.2.4) - you can delete them");
    if (hasPrefix(q, "Acrobatics.RSpeed2.")) info("Acrobatics.RSpeed2.* lines (Sprinter) are unused since 0.2.4 (Double Jump took its slot) - you can delete them");
  }
  if (need023) {
    String mp = q.getProperty("Mining.MSpeed.per");
    String fp = q.getProperty("Foraging.FSpeed.per");
    if (mp != null && !"0.01".equals(mp.trim())) warn("Mining.MSpeed.per=" + mp.trim() + " kept - since 0.2.3 it is pickaxe swing speed per level (0.01 = 1%, capped at +40%)");
    if (fp != null && !"0.01".equals(fp.trim())) warn("Foraging.FSpeed.per=" + fp.trim() + " kept - since 0.2.3 it is hatchet swing speed per level (0.01 = 1%, capped at +40%)");
  }
  return q;
}""")
M(cfg, r"""
public static synchronized String load() {
  java.util.Properties p = new java.util.Properties();
  boolean loaded = false;
  try {
    java.nio.file.Files.createDirectories(FILE.getParent(), new java.nio.file.attribute.FileAttribute[0]);
    if (!java.nio.file.Files.exists(FILE, new java.nio.file.LinkOption[0])) {
      writeAtomic(DEFAULTS.getBytes("UTF-8"));
      info("wrote default " + FILE);
    }
    java.io.InputStream in = java.nio.file.Files.newInputStream(FILE, new java.nio.file.OpenOption[0]);
    try { p.load(in); } finally { in.close(); }
    loaded = true;
  } catch (Throwable t) { warn("could not read trees.properties (built-in defaults used): " + t); }
  if (loaded) p = upgrade(p);
  apply(p);
  int on = 0;
  for (int i = 0; i < EN.length; i++) if (EN[i] && !@PKG@.TreeDefs.soon(i)) on++;
  int[] tl = TIER_LV;
  StringBuilder rt = new StringBuilder();
  for (int tt = 0; tt < @PKG@.TreeDefs.NT; tt++) {
    if (rate(tt) == XP_PER_DUST) continue;
    rt.append(rt.length() == 0 ? " (" : ", ").append(@PKG@.TreeDefs.TREES[tt]).append(' ').append(rate(tt));
  }
  if (rt.length() > 0) rt.append(')');
  return on + " of " + (@PKG@.TreeDefs.N - @PKG@.TreeDefs.SOON_N) + " nodes on (" + @PKG@.TreeDefs.SOON_N + " coming later), tiers " + tl[0] + "/" + tl[1] + "/" + tl[2] + "/" + tl[3] + "/" + tl[4] + "/" + tl[5] + ", 1 Dust per " + XP_PER_DUST + " XP" + rt.toString() + (SWING_ON ? "" : ", tool swing speed OFF") + (EXTRA_TOKENS > 0L || EXTRA_DUST > 0L ? " (DEBUG extra tokens/Dust on)" : "");
}""")

