# /tree class | /tree <class name> (3-letter prefixes after the tree names): null = not a class word; "" = open the class tab; else a refusal
M(cls, r"""
public static String cmdClass(java.util.UUID u, String a) {
  if (a == null) return null;
  String t = a.trim().toLowerCase();
  if (t.length() == 0) return null;
  int want = -1;
  if (t.equals("class") || t.equals("cla") || t.equals("clas")) want = -2;
  else {
    for (int i = 0; i < NC; i++) if (CLASSES[i].toLowerCase().equals(t)) want = i;
    if (want < 0 && t.length() >= 3) { for (int i = 0; i < NC; i++) if (CLASSES[i].toLowerCase().startsWith(t)) want = i; }
  }
  if (want == -1) return null;
  if (!@PKG@.TreeCfg.CLASS_ON) return "[Trees] Class trees are not switched on yet on this server";   // 0.3 fix H: players get no admin path
  String uc = classOf(u);
  int ci = classIdx(uc);
  if (ci < 0 && uc != null) return "[Trees] Your class " + uc + " has no skill tree yet - it comes in a later build";
  if (want >= 0 && ci < 0) return "[Trees] You have no class yet - choose one with /class (or create a profile)";
  if (want >= 0 && ci != want) return "[Trees] Your class is " + CLASSES[ci] + " - /tree class opens its tree";
  return "";
}""")

# 0.3.13: the class tree with the rebirth gate at a GIVEN class level (no SkyySkills call - safe under the TreeStore monitor)
M(cls, r"""
public static boolean[] intactAt(@PKG@.TreeData d, int ci, int lvl) {
  if (d == null || ci < 0 || ci >= NC || d.bad) return new boolean[NN];
  boolean[] own = ownOf(d, ci);
  if (d.crb[ci]) own = coveredBy(own, ci, d.corder[ci], ap(lvl < 0 ? 0 : lvl), gfOf(d, ci));
  return intactOf(own, ci);
}""")
# 0.3.13 THE AP CHECK of the update (spec 7.4): the grandfathered nodes are paid in order (the abilities, then the modifiers) while the free
# AP cover them; the rest stay grandfathered until the next respec. Pure (the caller holds the TreeStore monitor); { paid, kept } or null
M(cls, r"""
public static int[] gfCheck(@PKG@.TreeData d, int ci, int lvl) {
  if (d == null || d.bad || ci < 0 || ci >= NC || !d.cgfChk[ci] || lvl < 0) return null;
  if (d.crb[ci]) {   // a rebirth-gated tree: paying them could push a later pick out of the gate - they stay grandfathered (a respec frees them)
    int k0 = 0;
    for (int n = 0; n < NN; n++) if (d.cgf[ci * NN + n] && d.cown[ci * NN + n]) k0++;
    d.cgfChk[ci] = false;
    return new int[] { 0, k0 };
  }
  boolean[] it = intactAt(d, ci, lvl);
  int budget = ap(lvl) - spent(it, ci, gfOf(d, ci));
  int paid = 0;
  int kept = 0;
  for (int pass = 0; pass < 2; pass++) {
    for (int n = 0; n < NN; n++) {
      int j = ci * NN + n;
      if (!d.cgf[j] || !d.cown[j] || NROLE[n] != (pass == 0 ? 2 : 3)) continue;
      int c = @PKG@.TreeCfg.C_AP[j];
      if (it[n] && c <= budget) { d.cgf[j] = false; budget = budget - c; paid++; }
      else kept++;
    }
  }
  d.cgfChk[ci] = false;
  return new int[] { paid, kept };
}""")
