# BFS over the 26-neighbourhood from (ox, oy, oz) (already broken). Adds up to max matching, unplaced, not-recent blocks within the
# box; keeps scanning matched blocks up to scanMax for the leaves check (Tree Feller). leavesOut[0] = a Plant_Leaves_ block touches it.
M(abil, r"""
public static java.util.ArrayList flood(@WLD@ w, String wn, int ox, int oy, int oz, String match, boolean prefix, int max, int scanMax, int rh, int rv, boolean[] leavesOut, java.util.function.Function pf) {
  java.util.ArrayList out = new java.util.ArrayList();
  java.util.HashSet seen = new java.util.HashSet();
  java.util.ArrayDeque q = new java.util.ArrayDeque();
  seen.add(Long.valueOf(pos(ox, oy, oz)));
  q.add(new int[] { ox, oy, oz });
  boolean leaves = false;
  int matched = 0;
  int reads = 0;
  boolean leavesOnly = max <= 0 && leavesOut != null;   // 0.3.24: the read-only leaves check stops at the first leaves
  while (!q.isEmpty() && reads < 4000 && !(leavesOnly && leaves)) {
    int[] c = (int[]) q.poll();
    for (int dx = -1; dx <= 1; dx++) {
      for (int dy = -1; dy <= 1; dy++) {
        for (int dz = -1; dz <= 1; dz++) {
          if (dx == 0 && dy == 0 && dz == 0) continue;
          int x = c[0] + dx;
          int y = c[1] + dy;
          int z = c[2] + dz;
          if (Math.abs(x - ox) > rh || Math.abs(z - oz) > rh || Math.abs(y - oy) > rv) continue;
          Long k = Long.valueOf(pos(x, y, z));
          if (seen.contains(k)) continue;
          seen.add(k);
          reads++;
          String id = idAt(w, x, y, z);
          if (id == null || id.length() == 0) continue;
          if (!leaves && id.startsWith("Plant_Leaves_")) leaves = true;
          if (!matches(id, match, prefix)) continue;
          if (matched >= scanMax) continue;
          if (recent(wn, x, y, z) || placed(pf, wn, x, y, z)) continue;
          matched++;
          q.add(new int[] { x, y, z });
          if (out.size() < max) out.add(new @V3I@(x, y, z));
        }
      }
    }
  }
  if (leavesOut != null) leavesOut[0] = leaves;
  LASTREADS = reads;
  return out;
}""")
# 0.2.1 Tree Feller (Tree-Fall-Spec 3.3): breadth-first on the cut's Y level ONLY, over the 8 horizontal neighbours - the 4 sides
# before the 4 diagonals - so the logs nearest the cut come first. TreeDefs.isLog(id, fam) = Wood_<W>_Trunk / _Trunk_Full (+ states)
# only, not placed, not broken by an ability in the last 5 s, |dx|, |dz| <= rh, at most max positions and 4000 reads. Never another Y level.
M(abil, r"""
public static java.util.ArrayList flatFlood(@WLD@ w, String wn, int ox, int oy, int oz, String fam, int max, int rh, java.util.function.Function pf) {
  java.util.ArrayList out = new java.util.ArrayList();
  if (max <= 0 || fam == null) return out;
  int[] ddx = new int[] { 1, -1, 0, 0, 1, 1, -1, -1 };
  int[] ddz = new int[] { 0, 0, 1, -1, 1, -1, 1, -1 };
  java.util.HashSet seen = new java.util.HashSet();
  java.util.ArrayDeque q = new java.util.ArrayDeque();
  seen.add(Long.valueOf(pos(ox, oy, oz)));
  q.add(new int[] { ox, oz });
  int reads = 0;
  while (!q.isEmpty() && reads < 4000 && out.size() < max) {
    int[] c = (int[]) q.poll();
    for (int n = 0; n < 8 && out.size() < max; n++) {
      int x = c[0] + ddx[n];
      int z = c[1] + ddz[n];
      if (Math.abs(x - ox) > rh || Math.abs(z - oz) > rh) continue;
      Long k = Long.valueOf(pos(x, oy, z));
      if (seen.contains(k)) continue;
      seen.add(k);
      reads++;
      String id = idAt(w, x, oy, z);
      if (!@PKG@.TreeDefs.isLog(id, fam)) continue;
      if (recent(wn, x, oy, z) || placed(pf, wn, x, oy, z)) continue;
      q.add(new int[] { x, z });
      out.add(new @V3I@(x, oy, z));
    }
  }
  return out;
}""")
M(abil, r"""
public static @V3I@ pickNeighbour(@WLD@ w, String wn, int x0, int y0, int z0, String id, java.util.function.Function pf) {
  java.util.ArrayList c = new java.util.ArrayList();
  for (int dx = -1; dx <= 1; dx++) {
    for (int dy = -1; dy <= 1; dy++) {
      for (int dz = -1; dz <= 1; dz++) {
        if (dx == 0 && dy == 0 && dz == 0) continue;
        int x = x0 + dx;
        int y = y0 + dy;
        int z = z0 + dz;
        if (!id.equals(blockIdAt(w, x, y, z))) continue;
        if (recent(wn, x, y, z) || placed(pf, wn, x, y, z)) continue;
        c.add(new @V3I@(x, y, z));
      }
    }
  }
  if (c.isEmpty()) return null;
  return (@V3I@) c.get(java.util.concurrent.ThreadLocalRandom.current().nextInt(c.size()));
}""")
# the engine's own multi-block break (BreakBlockInteraction pattern): each position fires a real BreakBlockEvent on the player
M(abil, r"""
public static int breakList(@PR@ pr, @WLD@ w, String wn, java.util.ArrayList list) {
  if (list == null || list.isEmpty()) return 0;
  java.util.UUID u = pr.getUuid();
  if (ACTIVE.containsKey(u)) return 0;
  @REF@ r = pr.getReference();
  if (r == null || !r.isValid()) return 0;
  @ST@ st = r.getStore();
  @IS@ held = @INVC@.getItemInHand(st, r);
  if (held == null || held.isEmpty()) return 0;
  mark(wn, list);
  ACTIVE.put(u, Boolean.TRUE);
  int n = 0;
  try {
    java.util.List pl = list;
    n = @BHU@.performBlockBreak(r, held, pl, 4096, st, w.getChunkStore().getStore());
  } catch (Throwable t) {
    if (!BREAK_FAILED) { BREAK_FAILED = true; @PKG@.TreeCfg.warn("tree ability break failed (logged once): " + t); }
  }
  ACTIVE.remove(u);
  return n;
}""")
M(abil, r"""
public static boolean spread(@PR@ pr, String wn, int x, int y, int z, String id) {
  @WLD@ w = worldOf(pr, wn);
  if (w == null || id == null || id.length() == 0) return false;
  java.util.function.Function pf = placedFn();
  if (pf == null) return false;
  @V3I@ v = pickNeighbour(w, wn, x, y, z, id, pf);
  if (v == null) return false;
  java.util.ArrayList l = new java.util.ArrayList();
  l.add(v);
  int n = breakList(pr, w, wn, l);
  if (n > 0) @PKG@.TreeMsg.add(pr.getUuid(), "Spread", (long) n);
  return n > 0;
}""")
M(abil, r"""
public static boolean ready(java.util.UUID u, String what) {
  Object o = CD.get(u.toString() + "|" + what);
  return o == null || ((Long) o).longValue() <= System.currentTimeMillis();
}""")
# 0.3.24 server budget: how many of `want` ability blocks fit in tick `slot` (50 ms); all players together at most BUDGET
M(abil, r"""
public static synchronized int budgetAt(long slot, int want) {
  if (want <= 0) return 0;
  if (slot != BSLOT) { BSLOT = slot; BUSED = 0; }
  int left = BUDGET - BUSED;
  int g = want < left ? want : left;
  if (g < 0) g = 0;
  if (g < want) BHITS = BHITS + 1L;
  BUSED = BUSED + g;
  return g;
}""")
M(abil, r"""
public static java.util.ArrayList budget(java.util.ArrayList l) {
  int g = budgetAt(System.currentTimeMillis() / 50L, l.size());
  if (g >= l.size()) return l;
  if (!BUDGET_TOLD) { BUDGET_TOLD = true; @PKG@.TreeCfg.warn("Vein Burst / Tree Feller hit the server budget (" + BUDGET + " blocks a tick, all players together) - the rest of that break was skipped (logged once)"); }
  return new java.util.ArrayList(l.subList(0, g));
}""")
# 0.3.24: the ore Vein Burst at total level max breaks: exactly max (at most VEIN_CAP) connected, unplaced blocks of the same id, 26 neighbours
M(abil, r"""
public static java.util.ArrayList veinPick(@WLD@ w, String wn, int x, int y, int z, String id, int max, java.util.function.Function pf) {
  int m = max > VEIN_CAP ? VEIN_CAP : max;
  if (m <= 0 || id == null || id.length() == 0) return new java.util.ArrayList();
  int rad = @PKG@.TreeCfg.RADIUS;
  return flood(w, wn, x, y, z, id, false, m, m, rad, rad, null, pf);
}""")
# 0.3.24: arm the cooldown only when there is one (0 = every break); { true = the chat line was sent }
M(abil, r"""
public static void fired(@PR@ pr, String what, long cd, String line, String label, int n) {
  java.util.UUID u = pr.getUuid();
  if (cd > 0L) CD.put(u.toString() + "|" + what, Long.valueOf(System.currentTimeMillis() + cd));
  if (!@PKG@.TreeStore.notifyOn(u, "trees.abilities")) return;
  if (cd > 0L) @PKG@.TreeMsg.say(pr, line + " (ready again in " + (cd / 1000L) + " s)", "#ffc300");
  else @PKG@.TreeMsg.add(u, label, (long) n);
}""")
M(abil, r"""
public static boolean vein(@PR@ pr, String wn, int x, int y, int z, String id, int max) {
  java.util.UUID u = pr.getUuid();
  if (max <= 0 || !ready(u, "vein")) return false;
  @WLD@ w = worldOf(pr, wn);
  if (w == null) return false;
  java.util.function.Function pf = placedFn();
  if (pf == null) return false;
  java.util.ArrayList l = veinPick(w, wn, x, y, z, id, max, pf);
  if (l.isEmpty()) return false;
  l = budget(l);
  if (l.isEmpty()) return false;
  int n = breakList(pr, w, wn, l);
  if (n <= 0) return false;
  fired(pr, "vein", @PKG@.TreeCfg.VEIN_CD_MS, "Vein Burst! +" + n + " ore", "ore (Vein Burst)", n);
  return true;
}""")
M(abil, r"""
public static boolean feller(@PR@ pr, String wn, int x, int y, int z, String id, int max) {
  java.util.UUID u = pr.getUuid();
  if (max <= 0 || !ready(u, "feller")) return false;
  String fam = @PKG@.TreeDefs.logFamily(id);
  if (fam == null || !@PKG@.TreeDefs.isLog(id, fam)) return false;
  @WLD@ w = worldOf(pr, wn);
  if (w == null) return false;
  java.util.function.Function pf = placedFn();
  if (pf == null) return false;
  java.util.ArrayList l = flatFlood(w, wn, x, y, z, fam, max, @PKG@.TreeCfg.RADIUS, pf);
  if (l.isEmpty()) return false;
  if (@PKG@.TreeCfg.FELLER_LEAVES) {
    boolean[] leaves = new boolean[1];
    flood(w, wn, x, y, z, fam, true, 0, 256, @PKG@.TreeCfg.RADIUS, @PKG@.TreeCfg.FELLER_H, leaves, pf);
    if (!leaves[0]) return false;
  }
  l = budget(l);   // 0.3.24: the server-wide tick budget
  if (l.isEmpty()) return false;
  int n = breakList(pr, w, wn, l);
  if (n <= 0) return false;
  fired(pr, "feller", @PKG@.TreeCfg.FELLER_CD_MS, "Tree Feller! +" + n + (n == 1 ? " log" : " logs") + " on this level", "logs (Tree Feller)", n);   // 0.3.24: cooldown 0 = every cut
  return true;
}""")

# ================= 0.3.6 LIFELONG TOOL PERKS (tools/trees_0_3_6_patch.py): Vein Mine / Tree Feller levels of the player's own lifelong
# pickaxe / hatchet (SkyyGear 0.3.0+: gear:fn:lifelong + gear:fn:perk) stack on the tree level, total capped at 8 (the 2026-10-10 lock).
# Read on break only (TreeGather.run), cached 5 s per player per kind in LLC (UUID -> Object[2] { Object[] { uid, Integer perk, Long
# until } per kind }); dropped on profile switch (TreeTick) and on leave (TreeSaver.retainOnline). Never throws.
F(abil, "public static final java.util.concurrent.ConcurrentHashMap LLC = new java.util.concurrent.ConcurrentHashMap();")
F(abil, 'public static final String[] LLKIND = new String[] { "pickaxe", "hatchet" };')
F(abil, 'public static final String[] LLPERK = new String[] { "vein", "fell" };')
F(abil, "public static final int LLCAP = 10;")   # 0.3.21 (gear.md 2026-10-16 "the tool can cap at like 6 and the tree can give like 4 for a total of 10"; was 8)
F(abil, "public static final long LLTTL = 5000L;")
F(abil, "public static final long[] LLN = new long[3];")   # 0 bridge reads, 1 cache hits, 2 abilities fired above the tree's own level
# the uid of a lifelong SkyyGear tool document (ll=1, not retired) on these item metadata, else null
M(abil, r"""
public static String llUid(@BD@ md) {
  try {
    if (md == null) return null;
    @BV@ g = md.get("SkyyGear");
    if (g == null || !g.isDocument()) return null;
    @BD@ d = g.asDocument();
    @BV@ ll = d.get("ll");
    if (ll == null || !ll.isNumber() || ll.asNumber().intValue() != 1) return null;
    @BV@ rt = d.get("lrt");
    if (rt != null && rt.isNumber() && rt.asNumber().intValue() == 1) return null;
    @BV@ lu = d.get("lu");
    if (lu == null || !lu.isString()) return null;
    String x = lu.asString().getValue();
    if (x == null || x.length() == 0) return null;
    return x;
  } catch (Throwable t) { return null; }
}""")
# { profile's lifelong uid of kind k (null = none / SkyyGear absent / off), Integer perk level 0-8, Long until } - asked at most every 5 s
M(abil, r"""
public static Object[] llEntry(java.util.UUID u, int k) {
  long now = System.currentTimeMillis();
  Object o = LLC.get(u);
  Object[] row = null;
  if (o instanceof Object[]) row = (Object[]) o;
  if (row != null && row.length == 2 && row[k] instanceof Object[]) {
    Object[] c = (Object[]) row[k];
    long until = ((Long) c[2]).longValue();
    if (now < until && until - now <= LLTTL) { LLN[1] = LLN[1] + 1L; return c; }
  }
  String uid = null;
  int pk = 0;
  java.util.function.Function lf = @PKG@.TreeCalc.fn("gear:fn:lifelong");
  java.util.function.Function pf = @PKG@.TreeCalc.fn("gear:fn:perk");
  if (lf != null && pf != null) {
    try {
      Object a = lf.apply(new Object[] { u, LLKIND[k] });
      if (a instanceof String && ((String) a).length() > 0) uid = (String) a;
      if (uid != null) {
        Object b = pf.apply(new Object[] { u, LLKIND[k], LLPERK[k] });
        if (b instanceof Number) pk = ((Number) b).intValue();
      }
    } catch (Throwable t) { uid = null; pk = 0; }
  }
  if (pk < 0) pk = 0;
  if (pk > LLCAP) pk = LLCAP;
  LLN[0] = LLN[0] + 1L;
  Object[] e = new Object[] { uid, Integer.valueOf(pk), Long.valueOf(now + LLTTL) };
  Object[] nr = new Object[2];
  if (row != null && row.length == 2) { nr[0] = row[0]; nr[1] = row[1]; }
  nr[k] = e;
  LLC.put(u, nr);
  return e;
}""")
# the perk level of kind k (0 Vein Mine on the pickaxe, 1 Tree Feller on the hatchet) when md is the player's OWN lifelong tool of that kind
M(abil, r"""
public static int llPerk(java.util.UUID u, int k, @BD@ md) {
  if (u == null || k < 0 || k > 1) return 0;
  String lu = llUid(md);
  if (lu == null) return 0;
  Object[] e = llEntry(u, k);
  if (!lu.equals(e[0])) return 0;
  return ((Integer) e[1]).intValue();
}""")
# tree level + tool level, total capped at LLCAP 10 (0.3.21; was 8 - a tree level above it - an admin-raised max - is kept, never cut)
M(abil, r"""
public static int llTotal(int eff, int pk) {
  if (pk <= 0) return eff;
  int t = eff + pk;
  int cap = eff > LLCAP ? eff : LLCAP;
  return t > cap ? cap : t;
}""")
# the value Vein Burst (i = MVein, k 0) / Tree Feller (i = FFeller, k 1) fires with: cur (the tree alone, 0.3.5) unless the held item is
# the player's own lifelong tool of that kind with perk levels; a node switched off by the admin or the player stays off.
# FIX (critic HIGH, docs/answered/gear.md LOCKED 2026-10-10 "lvl 1 breaks 1 extra block. lvl 2 breaks 2 and so on. capped at 8"):
#   Vein Mine (k 0): each tool level that fits under the total cap of 8 adds exactly ONE more ore on top of the tree's own Vein Burst
#   number (tree 0 + Vein Mine 3 = 3 extra ore; tree 3 (10) + 3 = 13; tree 5 (14) + 3 = 17); the tree's own 4 + 2 x level is untouched.
#   Tree Feller (k 1): the total level reads the locked feller.logs table (the existing rule), as before.
M(abil, r"""
public static double llValue(java.util.UUID u, int i, int k, double cur, @BD@ md) {
  int pk = llPerk(u, k, md);
  if (pk <= 0) return cur;
  if (i < 0 || i >= @PKG@.TreeDefs.N || !@PKG@.TreeCfg.EN[i]) return cur;
  @PKG@.TreeData d = @PKG@.TreeStore.data(u);
  if (d == null || d.off[i]) return cur;
  int e = @PKG@.TreeCalc.eff(d, i);
  int t = llTotal(e, pk);
  double v;
  if (k == 0) v = cur + (double) (t - e);
  else v = @PKG@.TreeFx.value(i, t);
  if (v <= cur) return cur;
  LLN[2] = LLN[2] + 1L;
  return v;
}""")
# the metadata of the item in the breaker's hand (world thread; the call breakList makes) - null when none / not readable
M(abil, r"""
public static @BD@ heldMd(@PR@ pr) {
  try {
    if (pr == null) return null;
    @REF@ r = pr.getReference();
    if (r == null || !r.isValid()) return null;
    @IS@ h = @INVC@.getItemInHand(r.getStore(), r);
    if (h == null || h.isEmpty()) return null;
    return h.getMetadata();
  } catch (Throwable t) { return null; }
}""")
# gear:perk:readers (SkyyGear GearLL.perkOn): cur's words without vein / fell / swing, plus "vein,fell,swing" when add (0.3.21: + swing =
# SkyyGear 0.3.17's Breaking Speed line, applied by TreeSwing)
M(abil, r"""
public static String readersWith(String cur, boolean add) {
  StringBuilder sb = new StringBuilder();
  if (cur != null) {
    String[] xs = cur.split(",");
    for (int i = 0; i < xs.length; i++) {
      String x = xs[i].trim();
      if (x.length() == 0 || x.equals("vein") || x.equals("fell") || x.equals("swing")) continue;
      if (sb.length() > 0) sb.append(",");
      sb.append(x);
    }
  }
  if (add) {
    if (sb.length() > 0) sb.append(",");
    sb.append("vein,fell,swing");
  }
  return sb.toString();
}""")
M(abil, r"""
public static void readers(boolean add) {
  try {
    java.util.Map b = @PKG@.TreeStore.bridge();
    Object o = b.get("gear:perk:readers");
    if (o != null && !(o instanceof String)) { @PKG@.TreeCfg.warn("gear:perk:readers is not text - left alone (SkyyGear may not offer Vein Mine / Tree Feller / Breaking Speed)"); return; }
    String n = readersWith((String) o, add);
    if (n.length() == 0) b.remove("gear:perk:readers");
    else b.put("gear:perk:readers", n);
    // 0.3.21: SkyyAccessories 0.5.22 publishes swing.<skill> (skill:bonus source accessories) only while this reader is listed
    if (add) b.put("skill:bonus:reads:swing", Boolean.TRUE);
    else b.remove("skill:bonus:reads:swing", Boolean.TRUE);   // shutdown: removes only our own TRUE (another mod's value stays)
  } catch (Throwable t) { }
}""")

# ================= TreeGather: the skill:on:gather listener (ITEM / EXTRA / COINS / BREAK) =================
gat.addInterface(pool.get("java.util.function.Function"))
F(gat, "public static Object INSTANCE;")
F(gat, "public static Object FELLED;")
F(gat, "public static boolean OFF_THREAD_TOLD = false;")
F(gat, "public static boolean FAILED_ONCE = false;")
C(gat, "public TreeGather() { }")
M(gat, r"""
public static boolean roll(double p) {
  if (p <= 0.0) return false;
  if (p >= 1.0) return true;
  return java.util.concurrent.ThreadLocalRandom.current().nextDouble() < p;
}""")
M(gat, r"""
public static String pick(Object list) {
  if (!(list instanceof String[])) return null;
  String[] xs = (String[]) list;
  if (xs.length == 0) return null;
  return xs[java.util.concurrent.ThreadLocalRandom.current().nextInt(xs.length)];
}""")
M(gat, r"""
public static @PLA@ player(@PR@ pr, String wn) {
  if (@PKG@.TreeAbil.worldOf(pr, wn) == null) return null;
  @REF@ r = pr.getReference();
  return (@PLA@) r.getStore().getComponent(r, @PLA@.getComponentType());
}""")
# storage > hotbar > backpack, dropped at the feet when full (SkyySkills Perks.give / SkyySacks 0.6.5 output path)
M(gat, r"""
public static void giveItem(@PR@ pr, String wn, String id) {
  if (!@PKG@.TreeAbil.itemOk(id)) return;
  @PLA@ p = player(pr, wn);
  if (p == null) return;
  @REF@ r = pr.getReference();
  @SIC@.addOrDropItemStack(r.getStore(), r, p.getInventory().getCombinedStorageHotbarBackpack(), new @IS@(id, 1));
  @PKG@.TreeMsg.add(pr.getUuid(), @PKG@.TreeDefs.label(id), 1L);
}""")
M(gat, r"""
public static void giveDrops(@PR@ pr, String wn, @BTY@ bt, boolean harvest, int times) {
  java.util.function.Function f = @PKG@.TreeCalc.fn("skill:fn:drops");
  if (f == null) return;
  @PLA@ p = player(pr, wn);
  if (p == null) return;
  @REF@ r = pr.getReference();
  for (int k = 0; k < times; k++) {
    Object o = f.apply(new Object[] { bt, Boolean.valueOf(harvest) });
    if (!(o instanceof java.util.List)) return;
    java.util.List l = (java.util.List) o;
    int n = 0;
    for (int i = 0; i < l.size(); i++) {
      Object e = l.get(i);
      if (!(e instanceof @IS@)) continue;
      @IS@ is = (@IS@) e;
      if (is.isEmpty() || is.getItemId() == null) continue;
      @SIC@.addOrDropItemStack(r.getStore(), r, p.getInventory().getCombinedStorageHotbarBackpack(), is);
      n++;
    }
    if (n > 0) @PKG@.TreeMsg.add(pr.getUuid(), "extra drops", 1L);
  }
}""")
# 0.3.14 BASE TREE SAP (Skyy 2026-10-15 "lets slightly boost sap drops to make T1 easier and faster to unlock"): every chopped natural log
