# the gate of every row number (index 1..7): min(5 x (n - 1), the HOOKED ranks of the rows below n, all branches) - fix round: fixed at build
# time (GATES), never from the live state, so a row (and its free ability) never re-locks while the server runs
M(v3c, r"""
public static int[] gates(int tv) {
  int[] g = new int[8];
  if (tv < 0 || tv >= NV) return g;
  for (int n = 0; n < 8; n++) g[n] = GATES[tv * 8 + n];
  return g;
}""")
# the 0.3 node levels of the skill trees' ranks + the perks of open rows -> d.lv (TreeCalc.eff caps them at each node's max)
M(v3c, r"""
public static void derive(@PKG@.TreeData d) {
  if (d == null || d.bad) return;
  int[] lv = new int[@PKG@.TreeDefs.N];
  for (int tv = NCV; tv < NV; tv++) {
    for (int u = TU0[tv]; u < TU0[tv] + TUN[tv]; u++) {
      int o = UHO[u];
      if (UHK[u] == 2 && d.rk[u] > 0 && o >= 0 && o < lv.length) lv[o] = lv[o] + d.rk[u] * UHL[u];
    }
    int sp = -1;
    int[] g = null;
    for (int r = TR0[tv]; r < TR0[tv] + TRN[tv]; r++) {
      if (RFK[r] != 2 || RFO[r] < 0 || RFO[r] >= lv.length) continue;
      if (g == null) { g = gates(tv); sp = spent(d, tv); }
      if (sp >= g[RNUM[r]]) lv[RFO[r]] = lv[RFO[r]] + RFL[r];
    }
  }
  @PKG@.TreeStore.v3lv(d, lv);
}""")
# the class ability lines the player has (A1 A2 A3 A4a A4b): their row is open, or they are grandfathered (kept until a respec)
M(v3c, r"""
public static boolean[] lines(@PKG@.TreeData d, int ci) {
  boolean[] o = new boolean[5];
  if (d == null || ci < 0 || ci >= NCV) return o;
  int sp = spent(d, ci);
  int[] g = gates(ci);
  for (int r = TR0[ci]; r < TR0[ci] + TRN[ci]; r++) {
    if (RFK[r] != 1) continue;
    int li = lineIdx(RFLINE[r]);
    if (li < 0) continue;
    if (sp >= g[RNUM[r]] || d.gfa[ci * 5 + li]) o[li] = true;
  }
  return o;
}""")
