# the key of one properties line ("" = a comment / blank line)
M(v3m, r"""
public static String keyOf(String body) {
  int n = body.length();
  int s = 0;
  while (s < n && (body.charAt(s) == ' ' || body.charAt(s) == '\t' || body.charAt(s) == '\f')) s++;
  if (s >= n || body.charAt(s) == '#' || body.charAt(s) == '!') return "";
  int e = s;
  while (e < n && body.charAt(e) != '=' && body.charAt(e) != ':' && body.charAt(e) != ' ' && body.charAt(e) != '\t') e++;
  return body.substring(s, e);
}""")
M(v3m, r"""
public static boolean contLine(String body) {
  int n = 0;
  for (int i = body.length() - 1; i >= 0 && body.charAt(i) == '\\'; i--) n++;
  return n % 2 == 1;
}""")
# the new file text: the kept lines byte for byte (comments, blank lines, name, quiet, note.swing, rb.lastTx; v=2 -> v=3 in place), then
# the v3 lines in the file's own line ending; add = the appended lines (without endings)
M(v3m, r"""
public static String newText(String text, java.util.ArrayList add) {
  String nl = text.indexOf("\r\n") >= 0 ? "\r\n" : "\n";
  String[] ls = text.split("\n", -1);
  StringBuilder out = new StringBuilder(text.length() + 512);
  boolean sawV = false;
  boolean cont = false;
  boolean keepCont = false;
  for (int j = 0; j < ls.length; j++) {
    String ln = ls[j];
    if (j == ls.length - 1 && ln.length() == 0) break;   // the ending of the last line
    boolean cr = ln.endsWith("\r");
    String body = cr ? ln.substring(0, ln.length() - 1) : ln;
    boolean keep;
    if (cont) keep = keepCont;
    else {
      String key = keyOf(body);
      if (key.length() == 0) keep = true;
      else if (key.equals("v")) { int at = body.indexOf('v'); ln = body.substring(0, at) + "v=3" + (cr ? "\r" : ""); body = "v=3"; keep = true; sawV = true; }
      else keep = key.equals("name") || key.equals("quiet") || key.equals("note.swing") || key.equals("rb.lastTx");
    }
    cont = contLine(body);
    keepCont = keep;
    if (keep) { out.append(ln); out.append('\n'); }
  }
  if (!sawV) out.append("v=3").append(nl);
  for (int i = 0; i < add.size(); i++) out.append((String) add.get(i)).append(nl);
  return out.toString();
}""")
